insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('unread-message-backlog-triage-sheet', 'Unread Message Backlog Triage Sheet', 'worksheet'::resource_kind, 'A sorting sheet for the pile of unanswered texts, emails and voicemails a client has been avoiding.', 'Use it to turn a shame-soaked backlog into three short lists the client can actually work through.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client open the inbox or message app in session and count, without reading, how many items are waiting. Then sort each one into reply in two lines, reply needs thought, or no reply needed. Most clients find the third pile is the largest and the first pile takes ten minutes. Watch for the urge to apologize at length in every reply; a one-line answer sent today beats a perfect one never sent. Agree on which two-line replies go out before the next session.', '[{"id": "f0", "type": "textarea", "label": "How many unanswered messages are waiting, roughly, and how long the oldest has sat:"}, {"id": "f1", "type": "textarea", "label": "Messages I can answer in two lines or fewer:"}, {"id": "f2", "type": "textarea", "label": "Messages that need real thought, and when I will give each one ten minutes:"}, {"id": "f3", "type": "textarea", "label": "Messages that need no reply at all, and why I kept them open anyway:"}, {"id": "f4", "type": "textarea", "label": "The story I tell myself about what the sender thinks of the delay:"}, {"id": "f5", "type": "textarea", "label": "The two-line replies I will send before next session:"}]'::jsonb, array['avoidance', 'planning', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('seasonal-shift-preparation-checklist', 'Seasonal Shift Preparation Checklist', 'worksheet'::resource_kind, 'A checklist for the weeks before a season changes, covering light, routine, social plans and the mood dips a client has seen before.', 'Use it to get ahead of a predictable seasonal slump instead of noticing it from the inside.', array['Adults']::text[], '25 minutes', 'Ask the client what the coming season has been like for them in past years, in plain detail: sleep, energy, how often they saw people, what they stopped doing. Then build the checklist from that history rather than from general advice. Items usually include a light and wake-time plan, two standing social commitments, one indoor activity they like, and an early-warning sign that tells them and someone else to check in. Revisit the sheet at the first sign rather than waiting for the season to settle in.', '[{"id": "f0", "type": "textarea", "label": "What the last two of these seasons looked like for me, honestly:"}, {"id": "f1", "type": "textarea", "label": "The first sign that the shift has started for me:"}, {"id": "f2", "type": "textarea", "label": "Light, wake time and movement plan for the coming months:"}, {"id": "f3", "type": "textarea", "label": "Two standing plans with people that stay on the calendar no matter what:"}, {"id": "f4", "type": "textarea", "label": "Who I will tell about the early-warning sign, and what I want them to do:"}, {"id": "f5", "type": "textarea", "label": "One indoor thing I enjoy that I will set up now, before I need it:"}]'::jsonb, array['planning', 'low mood', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('interruptions-at-work-log-and-reply-sheet', 'Interruptions at Work Log and Reply Sheet', 'worksheet'::resource_kind, 'A log of who interrupts a client at work, how, and what the client does, with a reply they can practice for each type.', 'Use it to spot the interruption pattern that eats the day and rehearse a short reply for it.', array['Adults']::text[], 'One work week', 'Clients who say they get nothing done rarely know where the time goes. For one week, have them tick each interruption with who, channel, and whether they stopped what they were doing. In session, group the ticks: most fall into two or three types. Draft one calm reply for each, such as I will come find you at eleven, and rehearse it. Watch for the belief that any pause makes them unhelpful; the log usually shows the interruptions that mattered were few.', '[{"id": "f0", "type": "textarea", "label": "Interruptions this week, with who, how (in person, message, call) and whether I stopped:"}, {"id": "f1", "type": "textarea", "label": "The two or three types that happened most:"}, {"id": "f2", "type": "textarea", "label": "What I actually did each time, and what it cost me later:"}, {"id": "f3", "type": "textarea", "label": "A one-line reply I can use for each type:"}, {"id": "f4", "type": "textarea", "label": "What I fear would happen if I used the reply:"}, {"id": "f5", "type": "textarea", "label": "The one reply I will try first, and with whom:"}]'::jsonb, array['self-monitoring', 'assertiveness', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('hard-conversation-countdown-planner', 'Hard Conversation Countdown Planner', 'worksheet'::resource_kind, 'A day-by-day planner for the week before a conversation the client has been putting off.', 'Use it to spread the preparation for a dreaded talk across a week so the day itself is not the first time they think it through.', array['Adults', 'Teens']::text[], 'One week', 'Once the client has picked the conversation and the date, work backward. Earlier days hold the quiet work: what they want from it, what they can live with, the one sentence they open with. Middle days hold rehearsal with you or a trusted person. The last day holds only logistics and a calming plan. Clients tend to either ruminate all week or avoid thinking until the hour; the countdown gives each day one small job and permission to stop there.', '[{"id": "f0", "type": "textarea", "label": "The conversation, with whom, and the date and place:"}, {"id": "f1", "type": "textarea", "label": "Seven days out: what I want from it, and what I could accept instead:"}, {"id": "f2", "type": "textarea", "label": "Five days out: my opening sentence, in my own words:"}, {"id": "f3", "type": "textarea", "label": "Three days out: who I rehearsed with, and what they noticed:"}, {"id": "f4", "type": "textarea", "label": "The day before: logistics and how I will settle myself beforehand:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what happened, and what I would keep for next time:"}]'::jsonb, array['communication', 'planning', 'assertiveness']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('tabs-open-in-my-head-brain-dump-sheet', 'Tabs Open in My Head Brain Dump Sheet', 'worksheet'::resource_kind, 'A single page for emptying every half-finished thought, errand and worry so the client can see what is actually open.', 'Use it to move a crowded mind onto paper and sort it into do, decide, and drop.', array['Adults', 'Teens']::text[], '20 minutes', 'Set a ten-minute timer and have the client write every open loop with no order and no judging. Fragments are fine. When the timer ends, go through the list together and mark each item do, decide or drop. Clients are often surprised by how many items are drops dressed as duties. Keep the dropped items on the sheet so the client sees they chose to let them go. Repeat weekly if the mind refills, which it will.', '[{"id": "f0", "type": "textarea", "label": "Everything open in my head right now, in no particular order:"}, {"id": "f1", "type": "textarea", "label": "Items I can do in under ten minutes this week:"}, {"id": "f2", "type": "textarea", "label": "Items that need a decision, and what the decision actually is:"}, {"id": "f3", "type": "textarea", "label": "Items I am dropping on purpose, and what I tell myself about letting them go:"}, {"id": "f4", "type": "textarea", "label": "How my head feels now compared with before the timer started:"}]'::jsonb, array['self-monitoring', 'planning', 'stress']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('worry-decision-tree-sheet', 'Worry Decision Tree Sheet', 'cbt'::resource_kind, 'A branching sheet that walks each worry through three questions and lands on an action, a scheduled time, or a let-go.', 'Use it to give a client a repeatable route from a worry to a decision instead of another loop.', array['Adults', 'Teens']::text[], '20 minutes, then daily', 'Draw the tree with the client: Is this about a real problem I can act on? If no, it goes to the let-go branch with a defusion or worry-time plan. If yes, can I act now? If yes, name the action. If no, write when, and park it. Run three recent worries through it in session so the client sees how often they stall at the first fork. The tree is not meant to settle whether a worry is true; it only decides what to do with it.', '[{"id": "f0", "type": "textarea", "label": "The worry, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "Is this about a real problem I can act on? Yes or no, and how I know:"}, {"id": "f2", "type": "textarea", "label": "If yes, can I act on it now? If so, the first step:"}, {"id": "f3", "type": "textarea", "label": "If not now, when exactly will I act, and where did I write it down?"}, {"id": "f4", "type": "textarea", "label": "If no action is possible, what will I do with the worry instead?"}, {"id": "f5", "type": "textarea", "label": "Where I usually get stuck on the tree:"}]'::jsonb, array['core CBT', 'worry', 'problem solving']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('ask-five-people-survey-sheet', 'Ask Five People Survey Sheet', 'cbt'::resource_kind, 'A sheet for testing a belief about how others would react by asking five real people the question.', 'Use it to replace a guess about other people''s judgments with their actual answers.', array['Adults', 'Teens']::text[], 'One week', 'Pick a belief that depends on how others think, such as people find it rude when someone leaves a party early. Help the client write a neutral question, choose five people they can ask without a long explanation, and predict each answer before asking. The gap between prediction and answer is the lesson. Watch for clients who pick only people they expect to agree, or who discount every answer as politeness; name both in advance.', '[{"id": "f0", "type": "textarea", "label": "The belief about other people that I want to test:"}, {"id": "f1", "type": "textarea", "label": "The neutral question I will ask, word for word:"}, {"id": "f2", "type": "textarea", "label": "The five people I will ask, and what I predict each will say:"}, {"id": "f3", "type": "textarea", "label": "What each person actually said:"}, {"id": "f4", "type": "textarea", "label": "How I explained away answers I did not expect:"}, {"id": "f5", "type": "textarea", "label": "What the five answers together tell me about the belief:"}]'::jsonb, array['core CBT', 'behavioral experiment', 'thinking traps']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('thinking-in-shades-zero-to-one-hundred-sheet', 'Thinking in Shades Zero to One Hundred Sheet', 'cbt'::resource_kind, 'A sheet that replaces an all-or-nothing verdict with a zero to one hundred rating and the points in between.', 'Use it to loosen a pass-or-fail judgment by asking what seventy, forty and ten percent would look like.', array['Adults', 'Teens']::text[], '15 minutes', 'Take a recent verdict the client gave themselves, such as I bombed the presentation. Draw a line from zero to one hundred and ask what zero would have looked like, what one hundred would have looked like, and then where the event really sits. Fill in a few midpoints so the scale has texture. Most clients land their event far from the end they named. The point is not to argue them up the scale but to show them the scale exists.', '[{"id": "f0", "type": "textarea", "label": "The all-or-nothing verdict I gave myself:"}, {"id": "f1", "type": "textarea", "label": "What a zero would actually have looked like:"}, {"id": "f2", "type": "textarea", "label": "What a one hundred would actually have looked like:"}, {"id": "f3", "type": "textarea", "label": "Where the real event sits on the line, and why there:"}, {"id": "f4", "type": "textarea", "label": "A fairer one-sentence description of what happened:"}]'::jsonb, array['core CBT', 'thinking traps', 'perfectionism']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('evidence-i-would-accept-in-advance-sheet', 'Evidence I Would Accept in Advance Sheet', 'cbt'::resource_kind, 'A sheet where the client names, before an experiment, exactly what evidence would count against their belief.', 'Use it to stop a belief from moving the goalposts after the result comes in.', array['Adults', 'Teens']::text[], '20 minutes', 'Beliefs survive experiments by redefining success afterward. Before the client runs a test, have them write what outcome would count as evidence against the belief, how much of it, and what they would be tempted to say to dismiss it. Sign and date it together. After the experiment, hold the result against the pre-written standard, not the standard the mind invents on the day. This works well paired with any behavioral experiment the client is already planning.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing, as a sentence I actually think:"}, {"id": "f1", "type": "textarea", "label": "The experiment, in one or two lines:"}, {"id": "f2", "type": "textarea", "label": "What result would count as evidence against the belief, specifically:"}, {"id": "f3", "type": "textarea", "label": "How much of that result I would need before it counts:"}, {"id": "f4", "type": "textarea", "label": "The excuses I predict I will make if that result happens:"}, {"id": "f5", "type": "textarea", "label": "After the experiment: what happened, held against what I wrote above:"}]'::jsonb, array['core CBT', 'behavioral experiment', 'thinking traps']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('vertical-arrow-for-a-rule-sheet', 'Vertical Arrow for a Rule Sheet', 'cbt'::resource_kind, 'A sheet that follows a personal rule, such as I must never let anyone down, to the belief about self and world beneath it.', 'Use it to find the deeper assumption a demanding rule is protecting before trying to loosen the rule.', array['Adults']::text[], '30 minutes', 'Rules like I must always be available feel like facts to the client. Ask what it would mean if the rule were broken, then what that would mean, and so on, writing each answer under the last until the client reaches something about who they are or how the world works. Stop when the answer repeats. Do not challenge anything on the way down; the descent is the work. Come back to the bottom belief in a later session with evidence and shades-of-gray tools.', '[{"id": "f0", "type": "textarea", "label": "The rule I live by, as I would say it:"}, {"id": "f1", "type": "textarea", "label": "If I broke that rule, what would that mean?"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what would it mean?"}, {"id": "f3", "type": "textarea", "label": "And if that were true, what would it mean about me or the world?"}, {"id": "f4", "type": "textarea", "label": "The belief at the bottom, in one sentence:"}, {"id": "f5", "type": "textarea", "label": "How it felt to see the rule and the belief written together:"}]'::jsonb, array['core CBT', 'core beliefs', 'perfectionism']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('willingness-and-action-plan-sheet', 'Willingness and Action Plan Sheet', 'act'::resource_kind, 'A one-page plan naming a valued goal, the actions toward it, and the thoughts, feelings and urges the client is willing to make room for.', 'Use it to pair a committed action with an honest inventory of what will show up on the way.', array['Adults', 'Teens']::text[], '30 minutes', 'Fill it in together. The goal is a behavior, not a feeling. The actions are small and dated. The middle section lists the exact thoughts, sensations and urges the client expects, named plainly rather than fought. The last section asks how willing they are, zero to ten, to have all of that in order to do the action, and what would make the step smaller if the number is low. Review it after the first action, not after the whole plan.', '[{"id": "f0", "type": "textarea", "label": "The value this is in the service of:"}, {"id": "f1", "type": "textarea", "label": "The goal, as something a camera could film me doing:"}, {"id": "f2", "type": "textarea", "label": "The actions, each with a day and time:"}, {"id": "f3", "type": "textarea", "label": "Thoughts, feelings, sensations and urges I expect to show up:"}, {"id": "f4", "type": "textarea", "label": "How willing I am, zero to ten, to have all of that and act anyway:"}, {"id": "f5", "type": "textarea", "label": "If the number is under seven, a smaller step I am willing to take instead:"}]'::jsonb, array['core ACT', 'committed action', 'willingness']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-thoughts-stream-log', 'Mindfulness of Current Thoughts Stream Log', 'act'::resource_kind, 'A daily log of a short practice watching thoughts come and go without answering them, and what the mind did instead.', 'Use it to build the habit of noticing thinking as an activity rather than a set of orders.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Teach the practice in session: eyes closed or lowered, attention on where thoughts seem to appear, each one labeled thinking or given a one-word tag, then left alone. Two to five minutes is enough. The log asks what the client noticed, how often they got pulled in, and what the pulling thought was. Clients often rate themselves on how quiet the mind was; redirect them to how often they noticed they had been pulled, which is the actual skill.', '[{"id": "f0", "type": "textarea", "label": "Day and length of the practice:"}, {"id": "f1", "type": "textarea", "label": "Roughly how many times I noticed I had been pulled into a thought:"}, {"id": "f2", "type": "textarea", "label": "The thought that pulled hardest today:"}, {"id": "f3", "type": "textarea", "label": "What I did when I noticed, in a few words:"}, {"id": "f4", "type": "textarea", "label": "One thing I learned about how my mind works this week:"}]'::jsonb, array['core ACT', 'mindfulness', 'defusion']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('values-bullseye-dartboard-home-practice', 'Values Bullseye Dartboard Home Practice', 'act'::resource_kind, 'A home version of the bullseye where the client marks weekly how close their actions landed to their values in four life areas.', 'Use it to turn a one-time values check into a weekly picture the client draws themselves.', array['Adults']::text[], 'Ten minutes weekly for a month', 'After an in-session bullseye, send the client home with four blank targets, one per week, quartered into work and study, relationships, health, and leisure. Each week they place an X per quarter: center means I lived this value fully, edge means not at all. The sheet then asks for one action next week that would move one X inward. Lay the four weeks side by side at the month''s end and talk about what moved and what did not.', '[{"id": "f0", "type": "textarea", "label": "The value I hold in each quarter: work and study, relationships, health, leisure:"}, {"id": "f1", "type": "textarea", "label": "Where I placed my X in each quarter this week, and what I did that put it there:"}, {"id": "f2", "type": "textarea", "label": "The quarter farthest from the center, and what got in the way:"}, {"id": "f3", "type": "textarea", "label": "One action next week that would move one X inward:"}, {"id": "f4", "type": "textarea", "label": "What I notice looking back over the weeks so far:"}]'::jsonb, array['core ACT', 'values', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('thanking-the-mind-for-its-suggestions-page', 'Thanking the Mind for Its Suggestions Page', 'act'::resource_kind, 'A practice page for replying to unhelpful thoughts with a brief thank-you and returning to what the client was doing.', 'Use it to give a client a light, repeatable defusion move for the thoughts that nag all day.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'Frame the mind as a well-meaning advisor that never stops offering suggestions. When a familiar thought arrives, the client says, silently or aloud, thanks, mind, and returns to the task. Practice in session with three thoughts the client brought. Watch for sarcasm turning into an argument with the thought; the tone is warm and brief. The page tracks which thoughts got a thank-you and what the client did next, which is the only part that matters.', '[{"id": "f0", "type": "textarea", "label": "Three thoughts my mind offers most often:"}, {"id": "f1", "type": "textarea", "label": "How I said thanks to each one today, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What I went back to doing right after:"}, {"id": "f3", "type": "textarea", "label": "Thoughts that would not take a thank-you, and what they wanted instead:"}, {"id": "f4", "type": "textarea", "label": "How the practice felt by the end of the week:"}]'::jsonb, array['core ACT', 'defusion', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('self-as-context-sky-and-weather-writing-page', 'Self-as-Context Sky and Weather Writing Page', 'act'::resource_kind, 'A guided writing page where the client describes themselves as the sky that holds every passing weather of thought and feeling.', 'Use it to help a client step back from the content of a hard week and notice the part of them that was there throughout.', array['Adults', 'Teens']::text[], '20 minutes', 'Read the metaphor aloud: weather changes constantly and the sky is never harmed by it. Then have the client write the week as weather, storm by storm, and finish with a paragraph from the sky''s point of view. Some clients find this abstract; anchor it by asking who was noticing the storm when it hit. Do not use this to minimize the weather. The sky can hold a hurricane and still be the sky.', '[{"id": "f0", "type": "textarea", "label": "This week''s weather: the thoughts and feelings that passed through, storm by storm:"}, {"id": "f1", "type": "textarea", "label": "Who was noticing each storm as it happened?"}, {"id": "f2", "type": "textarea", "label": "A paragraph written from the sky''s point of view about the week:"}, {"id": "f3", "type": "textarea", "label": "What stayed the same about me while the weather changed:"}, {"id": "f4", "type": "textarea", "label": "One moment I might remember the sky the next time a storm starts:"}]'::jsonb, array['core ACT', 'self-as-context', 'mindfulness']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('effectively-skill-what-works-here-sheet', 'Effectively Skill What Works Here Sheet', 'dbt'::resource_kind, 'A sheet for the mindfulness how skill of doing what works, applied to a situation where the client wants to be right instead.', 'Use it to help a client choose the effective move over the satisfying one in a specific situation.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent situation where the client knows they were right and it went badly anyway. Write what they wanted the outcome to be, what they did, and what would have worked, given the actual people and rules in the room rather than the ones that should exist. Being effective can feel like giving in; name that feeling and come back to the goal. End with one upcoming situation and the effective move planned in advance.', '[{"id": "f0", "type": "textarea", "label": "The situation where I was right and it still went badly:"}, {"id": "f1", "type": "textarea", "label": "What I actually wanted to happen:"}, {"id": "f2", "type": "textarea", "label": "What I did, and what it got me:"}, {"id": "f3", "type": "textarea", "label": "What would have worked, given the real people and rules involved:"}, {"id": "f4", "type": "textarea", "label": "The feeling that comes with choosing what works over being right:"}, {"id": "f5", "type": "textarea", "label": "An upcoming situation, and the effective move I will make:"}]'::jsonb, array['core DBT', 'mindfulness', 'interpersonal effectiveness']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotion-ride-along-card', 'Mindfulness of Current Emotion Ride-Along Card', 'dbt'::resource_kind, 'A pocket card for staying with an emotion as it rises, peaks and falls, noticing it in the body without acting on it.', 'Use it to give a client a step-by-step way to ride an emotion out instead of blocking or feeding it.', array['Adults', 'Teens']::text[], 'Ten minutes, as needed', 'Walk through the card in session with a mild emotion first. Name the emotion, find it in the body, describe the sensation as if to a scientist, notice the urge, and let the wave do what waves do while breathing. Clients tend to skip to problem solving; the card has no step for that. Afterward, log how long the peak lasted. Over time the log shows emotions ending on their own, which no amount of telling them can do.', '[{"id": "f0", "type": "textarea", "label": "The emotion I noticed, and how strong it was at the start, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body, and what the sensation was like:"}, {"id": "f2", "type": "textarea", "label": "The urge that came with it, and what I did instead of acting on it:"}, {"id": "f3", "type": "textarea", "label": "How long until it started to fall:"}, {"id": "f4", "type": "textarea", "label": "What I learned about this emotion from riding along:"}]'::jsonb, array['core DBT', 'emotion regulation', 'mindfulness']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('think-skill-for-a-grudge-sheet', 'THINK Skill for a Grudge Sheet', 'dbt'::resource_kind, 'A sheet applying the THINK steps to a person the client is holding a grudge against.', 'Use it to help a client find a kinder reading of someone''s behavior without pretending the hurt did not happen.', array['Adults', 'Teens']::text[], '25 minutes', 'THINK stands for Think about the other''s view, Have empathy, Interpretations that are kind, Notice how they are trying, and Kindness. Choose a grudge the client wants to loosen, not one tied to ongoing harm. Work each letter in order, writing the client''s answer even when it is grudging. The sheet does not ask them to forgive or reconnect; it only tries on a different reading. Watch for clients who use it to blame themselves instead.', '[{"id": "f0", "type": "textarea", "label": "The person and what they did, in two sentences:"}, {"id": "f1", "type": "textarea", "label": "Think: how might the situation look from their side?"}, {"id": "f2", "type": "textarea", "label": "Have empathy: what might they have been feeling at the time?"}, {"id": "f3", "type": "textarea", "label": "Interpretations: two other explanations for their behavior, even unlikely ones:"}, {"id": "f4", "type": "textarea", "label": "Notice: any way they have tried, however small, since then:"}, {"id": "f5", "type": "textarea", "label": "Kindness: one kind thing I could do or think, and whether I choose to:"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'anger']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('reality-acceptance-half-day-practice-plan', 'Reality Acceptance Half Day Practice Plan', 'dbt'::resource_kind, 'A plan for one half day spent practicing reality acceptance at every small annoyance, with a tally.', 'Use it to drill acceptance on traffic, spilled coffee and slow lines so the skill is there for bigger things.', array['Adults', 'Teens']::text[], 'Half a day', 'Choose a morning or afternoon. Every time something small goes wrong, the client notices the fight against it, says a short acceptance phrase, relaxes the face and hands, and tallies it. The tally is the point; most clients collect ten or more in a few hours and are surprised how much of the day is spent fighting what already happened. Debrief which annoyances were easy to accept, which were not, and what the hard ones had in common.', '[{"id": "f0", "type": "textarea", "label": "The half day I chose, and my acceptance phrase:"}, {"id": "f1", "type": "textarea", "label": "Tally of small things that went wrong, with a word for each:"}, {"id": "f2", "type": "textarea", "label": "The ones I accepted quickly:"}, {"id": "f3", "type": "textarea", "label": "The ones I kept fighting, and what they had in common:"}, {"id": "f4", "type": "textarea", "label": "How my body felt at the end of the half day compared with a usual one:"}]'::jsonb, array['core DBT', 'distress tolerance', 'radical acceptance']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('dialectical-dilemma-two-extremes-middle-path-sheet', 'Dialectical Dilemma Two Extremes Middle Path Sheet', 'dbt'::resource_kind, 'A sheet for mapping a dilemma the client swings between, such as too strict and too loose, and finding the middle path.', 'Use it to help a client see both poles they bounce between and describe a middle they have not yet tried.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a pattern the client swings on: letting everything slide then cracking down, or overworking then collapsing. Write each pole with what it protects against and what it costs. Then describe a middle path in behaviors, not attitudes: what it would look like on a Tuesday. Clients often believe the middle is weak or boring; ask what each extreme has actually delivered. Agree on one middle-path behavior to try this week.', '[{"id": "f0", "type": "textarea", "label": "The two extremes I swing between, in my own words:"}, {"id": "f1", "type": "textarea", "label": "What each extreme protects me from:"}, {"id": "f2", "type": "textarea", "label": "What each extreme costs me:"}, {"id": "f3", "type": "textarea", "label": "What a middle path would look like on an ordinary day, in behaviors:"}, {"id": "f4", "type": "textarea", "label": "The belief that makes the middle feel wrong:"}, {"id": "f5", "type": "textarea", "label": "One middle-path behavior I will try this week:"}]'::jsonb, array['core DBT', 'dialectics', 'walking the middle path']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('six-second-kiss-and-twenty-second-hug-pairing-card', 'Six Second Kiss and Twenty Second Hug Pairing Card', 'couples'::resource_kind, 'A card for building two brief daily rituals of physical connection, with each partner''s part and a week of ticks.', 'Use it to give a couple two small, timed moments of touch that happen regardless of the day''s mood.', array['Couples']::text[], 'One week', 'Agree in session on when each ritual happens, who initiates, and what either partner says if they are not up for it that day. The timing matters: six seconds is longer than most partners expect, and twenty seconds of a hug lets both settle. Partners tick each day they did it. Low-touch weeks are information, not failure. Use the card with couples where affection has become rare but neither wants to make the first move.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when I will initiate, and what I will say if I am not up for it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: when I will initiate, and what I will say if I am not up for it:"}, {"id": "f2", "type": "textarea", "label": "Ticks for each day this week we did the kiss, and each day we did the hug:"}, {"id": "f3", "type": "textarea", "label": "The day it felt most natural, and what made it so:"}, {"id": "f4", "type": "textarea", "label": "The day it did not happen, and what got in the way, without blame:"}, {"id": "f5", "type": "textarea", "label": "What each of us noticed about the week as a whole:"}]'::jsonb, array['couples', 'Gottman', 'connection']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('attachment-needs-translation-sheet-for-partners', 'Attachment Needs Translation Sheet for Partners', 'couples'::resource_kind, 'A sheet where each partner names what they do when they feel distant and what they actually need in that moment.', 'Use it to help partners read each other''s distance or pursuit as a need rather than an attack.', array['Couples']::text[], 'Full session', 'Each partner fills their column separately first. What I do when I feel disconnected, what it looks like from the outside, what I am really hoping for, and what helps me come back. Then they read each other''s columns aloud. Partners are often startled to learn that withdrawal and criticism were both asks for closeness. Help them write a short translation each can say in the moment, such as when I go quiet, I need you to stay nearby.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I do when I feel disconnected, and what it probably looks like to you:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I am really hoping for, and what helps me come back:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I do when I feel disconnected, and what it probably looks like to you:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I am really hoping for, and what helps me come back:"}, {"id": "f4", "type": "textarea", "label": "The translation sentence each of us will try saying in the moment:"}, {"id": "f5", "type": "textarea", "label": "What surprised each of us in the other''s column:"}]'::jsonb, array['couples', 'attachment', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('decision-making-styles-match-sheet-for-partners', 'Decision Making Styles Match Sheet for Partners', 'couples'::resource_kind, 'A sheet comparing how each partner likes to make decisions, from how much research to how fast, and where the styles collide.', 'Use it to turn repeated fights over decisions into a shared process both partners agreed to.', array['Couples']::text[], '45 minutes', 'Partners rate themselves on speed, research, who they consult, how much they revisit and how they handle regret. Then they rate each other and compare. The collisions are usually about pace: one partner feels rushed while the other feels stalled. Help them design a process for medium decisions, such as a research deadline and a decide-by date, and name which decisions each can make alone. Return to the sheet when a new decision stalls.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I make decisions, in speed, research, consulting and revisiting:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I make decisions, in speed, research, consulting and revisiting:"}, {"id": "f2", "type": "textarea", "label": "Where our styles collide, with a recent example:"}, {"id": "f3", "type": "textarea", "label": "What each of us feels in the collision (rushed, stalled, unheard):"}, {"id": "f4", "type": "textarea", "label": "A shared process for medium decisions, with dates:"}, {"id": "f5", "type": "textarea", "label": "Decisions each of us can make alone without checking in:"}]'::jsonb, array['couples', 'communication', 'problem solving']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('in-law-and-extended-family-boundaries-sheet-for-partners', 'In-Law and Extended Family Boundaries Sheet for Partners', 'couples'::resource_kind, 'A sheet for partners to agree on boundaries with each other''s families and who delivers each message.', 'Use it to get a couple on the same side about family demands before the next holiday or visit.', array['Couples']::text[], 'Full session', 'Each partner lists the family situations that cause friction between them, not with the relatives. Then they name the boundary they both want and agree that the partner related to that family delivers it. Watch for a partner who wants a boundary but wants the other to enforce it. Script the first message together in plain words. The sheet also asks what each partner needs from the other when a relative pushes back.', '[{"id": "f0", "type": "textarea", "label": "Partner A: situations with my family that cause friction between us:"}, {"id": "f1", "type": "textarea", "label": "Partner B: situations with my family that cause friction between us:"}, {"id": "f2", "type": "textarea", "label": "The boundary we both want for each situation:"}, {"id": "f3", "type": "textarea", "label": "Who delivers each message, and the words they will use:"}, {"id": "f4", "type": "textarea", "label": "What each of us needs from the other when a relative pushes back:"}, {"id": "f5", "type": "textarea", "label": "The next visit or event, and the one boundary we will hold at it:"}]'::jsonb, array['couples', 'boundaries', 'family']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('partner-appreciation-specifics-drill-card', 'Partner Appreciation Specifics Drill Card', 'couples'::resource_kind, 'A card that moves appreciation from thanks for everything to one specific act, its effect, and the trait it showed.', 'Use it to teach partners an appreciation that lands because it names a real moment.', array['Couples']::text[], '15 minutes, then daily', 'Generic thanks slides off. Teach the three-part form: what you did, what it did for me, what it says about you. Have each partner deliver one in session and watch the receiver''s face. Then each partner gives one a day for a week, written on the card. Watch for appreciations that are secretly requests, such as thanks for finally doing the dishes. Partners should say the appreciation out loud, not only write it.', '[{"id": "f0", "type": "textarea", "label": "Partner A, this week''s appreciations: what you did, what it did for me, what it says about you:"}, {"id": "f1", "type": "textarea", "label": "Partner B, this week''s appreciations: what you did, what it did for me, what it says about you:"}, {"id": "f2", "type": "textarea", "label": "The appreciation I received that landed most, and why:"}, {"id": "f3", "type": "textarea", "label": "An appreciation that came out as a complaint in disguise, rewritten:"}, {"id": "f4", "type": "textarea", "label": "What it was like to be noticed in specifics this week:"}]'::jsonb, array['couples', 'Gottman', 'appreciation']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('egg-carton-feelings-sorter-craft', 'Egg Carton Feelings Sorter Craft', 'kids'::resource_kind, 'A craft where the child labels each egg carton cup with a feeling and sorts small objects into the cups for moments from their day.', 'Use it to give a young child a hands-on way to name and sort feelings from the day with a parent.', array['Children']::text[], '30 minutes to make, then five minutes nightly', 'The child decorates a clean egg carton, drawing a face in each of six cups: happy, sad, mad, scared, excited, calm. Each evening the parent hands them six beans or buttons and asks about the day; the child drops a bean in a cup for each moment they name. The parent''s job is to ask what happened, not to correct the cup. After a week, look at which cups are fullest and whether that matches what the parent saw.', '[{"id": "f0", "type": "textarea", "label": "The six feelings in my carton, and the face I drew for each:"}, {"id": "f1", "type": "textarea", "label": "Tonight''s beans: which cups they went in, and what happened for each:"}, {"id": "f2", "type": "textarea", "label": "The cup that was fullest this week:"}, {"id": "f3", "type": "textarea", "label": "A feeling I had that did not have a cup, and the cup I might add:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what the sorting showed me about my child''s week:"}]'::jsonb, array['children', 'feelings', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('breathing-bubble-wand-slow-blow-practice', 'Breathing Bubble Wand Slow Blow Practice', 'kids'::resource_kind, 'A play practice where the child learns a slow exhale by blowing bubbles that do not pop, with the parent counting.', 'Use it to teach a slow out-breath to a child through something they already want to do.', array['Children']::text[], '15 minutes, then as needed', 'Hand the child a bubble wand and ask them to blow the biggest bubble they can. Fast breath pops it; a slow steady breath makes it grow. Let them discover this. The parent counts the slow breath aloud and later uses the same count, blow a bubble, when the child is upset and no wand is nearby. Practice when calm first. The sheet records how many slow breaths it took and what the child named the breath.', '[{"id": "f0", "type": "textarea", "label": "What happened when I blew fast, and what happened when I blew slow:"}, {"id": "f1", "type": "textarea", "label": "My name for the slow bubble breath:"}, {"id": "f2", "type": "textarea", "label": "How many slow breaths I did today, and the biggest bubble I made:"}, {"id": "f3", "type": "textarea", "label": "A time I was upset and did the bubble breath without a wand:"}, {"id": "f4", "type": "textarea", "label": "Parent note: the count I use, and when it has helped:"}]'::jsonb, array['children', 'breathing', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('rock-paper-scissors-share-game', 'Rock Paper Scissors Share Game', 'kids'::resource_kind, 'A turn game where the loser of each round shares a feeling, a favorite or a worry, and the winner listens and asks one question.', 'Use it to get a reluctant child talking in short safe bursts with a parent or in a small group.', array['Children', 'Groups']::text[], '15 minutes', 'Two players throw rock, paper, scissors. The loser draws a card: a feeling I had today, something I am proud of, something that bugs me, a worry. The winner listens and asks one question. Then they throw again. Keep it fast and light; the game shape takes the pressure off being asked directly. The parent plays too and shares honestly at a child''s level. Stop after ten rounds and ask which card was easiest and hardest.', '[{"id": "f0", "type": "textarea", "label": "The cards we used:"}, {"id": "f1", "type": "textarea", "label": "Something I shared when I lost a round:"}, {"id": "f2", "type": "textarea", "label": "A good question someone asked me:"}, {"id": "f3", "type": "textarea", "label": "The card that was easiest, and the one that was hardest:"}, {"id": "f4", "type": "textarea", "label": "Parent note: something my child shared that I had not heard before:"}]'::jsonb, array['children', 'play', 'communication', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('me-and-my-helpers-hanging-mobile-craft', 'Me and My Helpers Hanging Mobile Craft', 'kids'::resource_kind, 'A craft where the child hangs drawings of the people and things that help them from a hanger, with themselves in the middle.', 'Use it to make a child''s support network visible and hang it where they will see it.', array['Children']::text[], '40 minutes', 'The child draws themselves on a circle for the center and then one helper per card: a parent, a teacher, a pet, a blanket, a song. The parent helps punch holes and tie string to a hanger so the helpers float around the child. Talk about what each helper does, in the child''s words, as it goes on. Hang it in the bedroom. When the child is struggling later, the parent can point to the mobile and ask which helper could help right now.', '[{"id": "f0", "type": "textarea", "label": "The helpers I put on my mobile:"}, {"id": "f1", "type": "textarea", "label": "What each helper does for me, in my own words:"}, {"id": "f2", "type": "textarea", "label": "A helper I almost forgot and then added:"}, {"id": "f3", "type": "textarea", "label": "Where we hung the mobile:"}, {"id": "f4", "type": "textarea", "label": "Parent note: how I will use the mobile when my child is upset:"}]'::jsonb, array['children', 'support', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('worry-time-capsule-jar-craft', 'Worry Time Capsule Jar Craft', 'kids'::resource_kind, 'A craft where the child writes or draws a worry, seals it in a jar, and opens it with a parent one week later to see what happened.', 'Use it to teach a child that most worries pass or shrink, by letting them check their own evidence.', array['Children']::text[], '20 minutes, then ten minutes a week later', 'The child decorates a jar with a lid and writes or draws today''s biggest worry on a slip, with a guess about what will happen. The parent dates the slip and seals the jar. One week later they open it together and the child says what actually happened. Keep the slips in a second jar labeled worries that passed. The parent never says I told you so; the growing jar does the talking. Return to the full jar when a new worry feels enormous.', '[{"id": "f0", "type": "textarea", "label": "My worry today, and what I think will happen:"}, {"id": "f1", "type": "textarea", "label": "The day we will open the jar:"}, {"id": "f2", "type": "textarea", "label": "Opening day: what actually happened:"}, {"id": "f3", "type": "textarea", "label": "Was the real thing bigger, smaller or the same as my guess?"}, {"id": "f4", "type": "textarea", "label": "How many slips are in my worries that passed jar now:"}, {"id": "f5", "type": "textarea", "label": "Parent note: what I noticed when we opened the jar:"}]'::jsonb, array['children', 'worry', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('last-letter-feelings-word-chain-game', 'Last Letter Feelings Word Chain Game', 'game'::resource_kind, 'A circle game where each player names a feeling word starting with the last letter of the previous one, then a time they felt it.', 'Use it to grow a group''s feelings vocabulary and get quick, low-stakes sharing going.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Players sit in a circle. The first says a feeling word, such as proud. The next must say a feeling word starting with its last letter, such as disappointed, and name a time they felt it in one sentence. If a player is stuck for ten seconds, the group can offer a word and the player still gives the example. Play three rounds. Debrief: which words were new to someone, which feeling got named most, and which was hardest to find an example for.', '[{"id": "f0", "type": "textarea", "label": "Feeling words I had not thought of before this game:"}, {"id": "f1", "type": "textarea", "label": "The feeling I named and the time I felt it:"}, {"id": "f2", "type": "textarea", "label": "The letter that was hardest to find a feeling for:"}, {"id": "f3", "type": "textarea", "label": "A feeling someone else named that I have felt too:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how the group talked by round three:"}]'::jsonb, array['game', 'group', 'feelings']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('mystery-bag-guess-the-object-grounding-game', 'Mystery Bag Guess the Object Grounding Game', 'game'::resource_kind, 'A game where players reach into a bag, describe an object by touch alone in five words, and the group guesses it.', 'Use it to practice present-moment description in a group while keeping it fun.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Fill an opaque bag with ten ordinary objects: a key, a sponge, a pine cone, a spoon. Players take turns reaching in without looking, choosing one, and giving exactly five describing words about texture, temperature, weight and shape, no naming. The group guesses. A correct guess earns the describer and the guesser a point. Debrief on what it was like to attend only to touch and how the same attention could be used when a mind is racing.', '[{"id": "f0", "type": "textarea", "label": "The object I described, and my five words:"}, {"id": "f1", "type": "textarea", "label": "Whether the group guessed it, and which word gave it away:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about my attention while my hand was in the bag:"}, {"id": "f3", "type": "textarea", "label": "A moment outside the group where describing by touch might steady me:"}, {"id": "f4", "type": "textarea", "label": "The object that was hardest to describe:"}]'::jsonb, array['game', 'grounding', 'mindfulness', 'group']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('spot-the-change-observation-pairs-game', 'Spot the Change Observation Pairs Game', 'game'::resource_kind, 'A pairs game where one partner changes three small things about themselves and the other has to spot them.', 'Use it to practice looking outward and noticing detail, in a group or a family.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Pairs face each other for thirty seconds and look carefully. They turn back to back and one partner changes three things: untucks a sleeve, moves a bracelet, parts hair differently. They turn around and the other has one minute to spot the changes. Switch roles. Then play again with the whole room: three things changed while everyone closes their eyes. Debrief on where attention went, how it felt to be looked at closely, and when noticing others might help outside the room.', '[{"id": "f0", "type": "textarea", "label": "The three changes I spotted, and the one I missed:"}, {"id": "f1", "type": "textarea", "label": "The changes I made, and which one nobody caught:"}, {"id": "f2", "type": "textarea", "label": "What it was like to be looked at closely for thirty seconds:"}, {"id": "f3", "type": "textarea", "label": "Where my attention went when I was the one looking:"}, {"id": "f4", "type": "textarea", "label": "A place outside this room where noticing details about others might help me:"}]'::jsonb, array['game', 'attention', 'group']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('telephone-game-kind-message-edition', 'Telephone Game Kind Message Edition', 'game'::resource_kind, 'A whisper-down-the-line game where a kind message about a group member travels the circle and the group sees how it changed.', 'Use it to show how messages shift as they pass between people, and to land some kindness on the way.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'The leader whispers a specific kind sentence about one group member to the first player, who whispers it on. The last player says it aloud and the leader reads the original. Then the person it was about says how it felt to hear both versions. Rotate so everyone receives one. Debrief: what got lost, what got added, and how often that happens with messages about us that we only hear secondhand.', '[{"id": "f0", "type": "textarea", "label": "The message I received at the end of the line, and the original:"}, {"id": "f1", "type": "textarea", "label": "What changed between them:"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear a kind message about me, even changed:"}, {"id": "f3", "type": "textarea", "label": "A time I heard something about myself secondhand and believed the changed version:"}, {"id": "f4", "type": "textarea", "label": "What I want to do next time a message reaches me through other people:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('build-the-scene-prop-improv-game', 'Build the Scene Prop Improv Game', 'game'::resource_kind, 'A group improv game where players draw a feeling card and a random object and act a one-minute scene using both.', 'Use it to let a group rehearse expressing feelings in a playful frame with a built-in debrief.', array['Groups', 'Teens']::text[], '30 minutes', 'Two decks: feelings and ordinary objects such as an umbrella or a stapler. Two players draw one of each and have one minute to play a scene in which the feeling is clear and the object is used. The audience names the feeling at the end. Points for correct guesses. Rotate until everyone has played twice. Debrief on which feelings were easiest to show, which the group guessed wrong, and what cues people actually use to read feelings.', '[{"id": "f0", "type": "textarea", "label": "The feeling and object I drew, and what our scene was:"}, {"id": "f1", "type": "textarea", "label": "Whether the audience guessed the feeling, and what gave it away:"}, {"id": "f2", "type": "textarea", "label": "The feeling that was hardest to show without saying it:"}, {"id": "f3", "type": "textarea", "label": "A cue someone used that I read wrong:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about how my own feelings may look to other people:"}]'::jsonb, array['game', 'group', 'feelings', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('fireworks-and-loud-event-advance-plan-sheet', 'Fireworks and Loud Event Advance Plan Sheet', 'worksheet'::resource_kind, 'A plan for a known loud event, such as a holiday fireworks night, covering location, company, ear protection and an exit.', 'Use it to let a client decide in advance how they will meet a predictable loud night instead of being ambushed by it.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask what loud events are coming in the next two months and which have caught the client off guard before. For each, plan where they will be, who will be with them, what they will use to soften the sound, and a grounding move to run at the first bang. Decide in advance whether leaving is on the table and what leaving looks like. Clients often feel ashamed of planning around noise; frame it as the same care a person gives a bad knee before a hike.', '[{"id": "f0", "type": "textarea", "label": "Loud events coming up in the next two months, with dates:"}, {"id": "f1", "type": "textarea", "label": "Where I will be for each, and who will be with me:"}, {"id": "f2", "type": "textarea", "label": "What I will use to soften the sound (earplugs, distance, music):"}, {"id": "f3", "type": "textarea", "label": "The grounding move I will run at the first bang:"}, {"id": "f4", "type": "textarea", "label": "Whether leaving is an option, and what leaving looks like:"}, {"id": "f5", "type": "textarea", "label": "What I will tell the people I am with, if anything:"}]'::jsonb, array['PTSD and trauma', 'planning', 'grounding']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('knowing-then-versus-knowing-now-fairness-sheet', 'Knowing Then Versus Knowing Now Fairness Sheet', 'cbt'::resource_kind, 'A sheet separating what the client knew at the time of a hard event from what they know now, for a self-judgment built on hindsight.', 'Use it to loosen a should-have-known thought by putting the client back inside what they actually knew then.', array['Adults', 'Teens']::text[], '30 minutes, in session', 'Use this in session only, and only for a self-judgment the client has already named. Do not ask for the event''s details; the two columns need only what the client knew and could see at the time versus what they learned afterward. Most hindsight judgments collapse once the later knowledge is moved out of the then column. Keep the pace slow and pause for grounding if the client''s attention drifts. End with one fairer sentence they can carry.', '[{"id": "f0", "type": "textarea", "label": "The judgment I make about myself, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "What I actually knew at the time, and what I could see from where I stood:"}, {"id": "f2", "type": "textarea", "label": "What I only learned afterward:"}, {"id": "f3", "type": "textarea", "label": "Would I hold a friend to what they learned later? What would I say to them?"}, {"id": "f4", "type": "textarea", "label": "A fairer sentence about what I did with what I knew then:"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'self-blame']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('rough-night-morning-restart-values-page', 'Rough Night Morning Restart Values Page', 'act'::resource_kind, 'A page for the morning after a bad night of dreams or waking, choosing one valued action for the day regardless of how the night went.', 'Use it to give a client a way to start the day on purpose after a night the body did not let them rest.', array['Adults', 'Teens']::text[], 'Ten minutes on rough mornings', 'Bad nights often decide the whole day. This page does not ask about the dream; it asks about the morning. The client names the night as weather, chooses one small action tied to a value, and plans one kindness for a tired body. Keep the action small enough to do on four hours of sleep. Review a stack of these pages together and notice which values keep showing up; those are the anchors to build on.', '[{"id": "f0", "type": "textarea", "label": "The night, in one or two words, like a weather report:"}, {"id": "f1", "type": "textarea", "label": "How my body feels this morning, without judging it:"}, {"id": "f2", "type": "textarea", "label": "A value I want today to be about, even a little:"}, {"id": "f3", "type": "textarea", "label": "One small action toward that value that fits a tired day:"}, {"id": "f4", "type": "textarea", "label": "One kindness for my body today (rest, food, warmth, a walk):"}, {"id": "f5", "type": "textarea", "label": "How I will know I started today on purpose:"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'values', 'sleep']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('feet-on-the-floor-weight-shift-grounding-card', 'Feet on the Floor Weight Shift Grounding Card', 'dbt'::resource_kind, 'A pocket card for grounding through the feet: pressing, shifting weight and naming the surface, when a memory pulls the client away.', 'Use it to give a client a grounding move they can do seated in a meeting or standing in a line without anyone noticing.', array['Adults', 'Teens']::text[], 'Two minutes, as needed', 'Teach it seated first. Both feet flat, press the toes down and notice the floor pushing back, shift weight to the left foot and then the right, name the surface and the shoe silently, then count the points of contact. The card lists the steps in order. Practice it when calm so it is rehearsed when needed. Clients who float during triggers often find feet easier to locate than breath. Log where it was used and how long until the room came back.', '[{"id": "f0", "type": "textarea", "label": "Where I was when I used the card:"}, {"id": "f1", "type": "textarea", "label": "The steps I did, in order, and which one brought the room back most:"}, {"id": "f2", "type": "textarea", "label": "What the floor and my shoes felt like when I paid attention:"}, {"id": "f3", "type": "textarea", "label": "How long it took to feel present again:"}, {"id": "f4", "type": "textarea", "label": "A place I want to practice it before I need it there:"}]'::jsonb, array['PTSD and trauma', 'core DBT', 'grounding', 'distress tolerance']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('safe-spot-blanket-tent-build-and-play', 'Safe Spot Blanket Tent Build and Play', 'kids'::resource_kind, 'A build-and-play activity where the child and parent make a blanket tent, stock it with comfort items and practice going there to settle.', 'Use it to give a child a physical safe place at home and a parent-child routine for using it.', array['Children']::text[], '45 minutes to build, then as needed', 'The child designs the tent with chairs and blankets and chooses what goes inside: a flashlight, a stuffed animal, a book, a snack. The parent builds alongside and agrees on a signal the child can use to say I need the tent. Practice going in when calm, with the parent sitting at the opening. The tent is for settling, not for hiding from every hard thing; the parent decides when to invite the child out. If a child discloses something while settled, follow your reporting duties and keep the conversation steady.', '[{"id": "f0", "type": "textarea", "label": "What I put inside my tent, and why each thing helps:"}, {"id": "f1", "type": "textarea", "label": "My signal for I need the tent:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up does while I am in the tent:"}, {"id": "f3", "type": "textarea", "label": "A time I used the tent this week, and how long until I felt settled:"}, {"id": "f4", "type": "textarea", "label": "Parent note: how I will invite my child back out, and what I noticed about what helps:"}]'::jsonb, array['PTSD and trauma', 'children', 'safety', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('worrying-keeps-me-safe-belief-test-sheet', 'Worrying Keeps Me Safe Belief Test Sheet', 'cbt'::resource_kind, 'A sheet for testing the belief that worrying prevents bad things by tracking worried and unworried days against what happened.', 'Use it to let a client compare outcomes on days they worried hard with days they did not.', array['Adults', 'Teens']::text[], 'Two weeks', 'Many clients hold onto worry because it feels like insurance. Rate the belief zero to one hundred. Then for two weeks the client logs each day''s worry level and whether anything bad happened that worry could have prevented. Also log near misses that worry did nothing about. At review, lay the two columns side by side and re-rate the belief. Avoid arguing the logic in advance; the sheet works because the client collects their own days.', '[{"id": "f0", "type": "textarea", "label": "The belief: worrying about things keeps bad things from happening. How much I believe it, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "Each day: how much I worried, zero to ten, and what, if anything, went wrong:"}, {"id": "f2", "type": "textarea", "label": "Things that went wrong that no amount of worry would have stopped:"}, {"id": "f3", "type": "textarea", "label": "Things that went fine on the days I barely worried:"}, {"id": "f4", "type": "textarea", "label": "How much I believe it now, and what shifted:"}]'::jsonb, array['anxiety', 'core CBT', 'worry', 'behavioral experiment']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('worry-train-platform-watching-page', 'Worry Train Platform Watching Page', 'act'::resource_kind, 'A defusion page where the client stands on a platform and watches worry trains pull in and out without boarding one.', 'Use it to give a client an image for letting a worry pass through instead of riding it to the end of the line.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'Describe the station: trains arrive constantly, each labeled with a worry, doors open, and the client can board or stay on the platform. Boarding is what rumination feels like. Practice in session with a live worry: name the train, watch it idle, let it leave. Clients often report boarding without noticing; the skill is stepping off at the next stop, not never boarding. The page logs trains seen, trains boarded, and how far each ride went.', '[{"id": "f0", "type": "textarea", "label": "The trains that pulled in today, by label:"}, {"id": "f1", "type": "textarea", "label": "The one I boarded, and how far I rode before I noticed:"}, {"id": "f2", "type": "textarea", "label": "What I did to step off:"}, {"id": "f3", "type": "textarea", "label": "What the platform felt like while a train idled with the doors open:"}, {"id": "f4", "type": "textarea", "label": "A train I expect tomorrow, and my plan for it:"}]'::jsonb, array['anxiety', 'core ACT', 'defusion', 'worry']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('one-mindful-dishwashing-for-anxious-evenings-card', 'One-Mindful Dishwashing for Anxious Evenings Card', 'dbt'::resource_kind, 'A card for turning an evening chore into a mindfulness practice when anxiety peaks after dinner.', 'Use it to give a client an anchor for the anxious hour that is already part of their routine.', array['Adults', 'Teens']::text[], 'Ten minutes nightly for a week', 'Many clients find anxiety crests between dinner and bed. Instead of adding a practice, make one from the dishes. The card says: water temperature, the weight of each plate, the sound, the smell of the soap, one dish at a time, and each time the mind leaves, return to the plate in hand. No podcast, no phone propped on the counter. After a week, compare evenings with and without the practice. Any repeated chore works if the client has no dishes.', '[{"id": "f0", "type": "textarea", "label": "The chore I used, and the time of evening:"}, {"id": "f1", "type": "textarea", "label": "What I noticed with each sense that I usually miss:"}, {"id": "f2", "type": "textarea", "label": "Roughly how many times my mind left and I brought it back:"}, {"id": "f3", "type": "textarea", "label": "Where my anxiety sat before and after, zero to ten:"}, {"id": "f4", "type": "textarea", "label": "Whether the rest of the evening went differently, and how:"}]'::jsonb, array['anxiety', 'core DBT', 'mindfulness', 'evening']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('worry-listening-timer-agreement-for-partners', 'Worry Listening Timer Agreement for Partners', 'couples'::resource_kind, 'An agreement giving the anxious partner a timed daily worry hearing and the listening partner a clear end to it.', 'Use it to protect a couple''s evenings from unlimited worry talk while making sure the worry still gets heard.', array['Couples']::text[], 'One week', 'The worried partner often needs to say it out loud; the other often feels drafted into hours of reassurance. Agree on a daily window, usually ten to fifteen minutes, a time, and a signal when it ends. During the window the listener reflects and asks questions but does not fix or reassure. Outside it, worries get written for tomorrow''s window. Both partners log how it went. Expect the first days to feel rigid and the later ones to feel like relief.', '[{"id": "f0", "type": "textarea", "label": "Partner A (the one who worries): the time and length of our daily window, and what I will do with worries outside it:"}, {"id": "f1", "type": "textarea", "label": "Partner B (the one who listens): how I will listen in the window, and what I will not do:"}, {"id": "f2", "type": "textarea", "label": "Our signal that the window is over:"}, {"id": "f3", "type": "textarea", "label": "Each day: did we hold the window, and how did the rest of the evening go?"}, {"id": "f4", "type": "textarea", "label": "What each of us noticed by the end of the week:"}, {"id": "f5", "type": "textarea", "label": "What we want to change about the agreement:"}]'::jsonb, array['anxiety', 'couples', 'communication', 'worry']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('uncertainty-grab-bag-group-game', 'Uncertainty Grab Bag Group Game', 'game'::resource_kind, 'A group game where players draw unknown small tasks from a bag and complete them without asking what comes next.', 'Use it to let a group practice tolerating not knowing in a playful, low-stakes round.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Prepare a bag of folded slips with harmless surprise tasks: hum a tune, swap seats with someone, describe your morning in three words, stand on one foot for ten seconds. Players take turns drawing without peeking and must complete the task before the next draw. No one may ask what the other slips say. Rate the not-knowing before and after each draw. Debrief: how the uncertainty felt in the body, how it changed after the first draw, and where in life the same not-knowing shows up.', '[{"id": "f0", "type": "textarea", "label": "My not-knowing rating before my first draw, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "The tasks I drew, and my rating right before each one:"}, {"id": "f2", "type": "textarea", "label": "What the waiting felt like in my body:"}, {"id": "f3", "type": "textarea", "label": "How the not-knowing changed between the first draw and the last:"}, {"id": "f4", "type": "textarea", "label": "A place in my week where I face the same not-knowing, and what this game suggests:"}]'::jsonb, array['anxiety', 'game', 'uncertainty', 'group']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('getting-vertical-morning-sequence-sheet', 'Getting Vertical Morning Sequence Sheet', 'worksheet'::resource_kind, 'A sheet breaking the move from lying down to standing up into tiny numbered steps for mornings when the bed wins.', 'Use it to give a client a sequence small enough to start when getting up feels impossible.', array['Adults', 'Teens']::text[], '20 minutes to build, then mornings', 'Clients with low mood often describe getting up as one enormous act. Break it into steps so small they are almost silly: open eyes, move one foot to the edge, sit up, feet on floor, stand, walk to the window. Each step gets a number and a tick. The client is allowed to stop after any step and still count the morning as a win. Track which step is the usual sticking point and work on only that one. Pair the last step with daylight or water.', '[{"id": "f0", "type": "textarea", "label": "My steps from lying down to standing, numbered and as small as possible:"}, {"id": "f1", "type": "textarea", "label": "The step I usually get stuck on:"}, {"id": "f2", "type": "textarea", "label": "What I will do or say to myself at exactly that step:"}, {"id": "f3", "type": "textarea", "label": "This week''s ticks: how far down the list I got each morning:"}, {"id": "f4", "type": "textarea", "label": "What the morning was like on the days I reached the window:"}]'::jsonb, array['depression', 'behavioral activation', 'morning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('waiting-to-feel-like-it-trap-page', 'Waiting to Feel Like It Trap Page', 'act'::resource_kind, 'A page that examines the rule I will do it when I feel like it and plans a valued action that goes first, feeling or no feeling.', 'Use it to help a client act ahead of motivation instead of waiting for a mood that is not coming on schedule.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask how long the client has been waiting to feel like doing the thing. Write the rule out in full and then list the actions it has postponed. Introduce the reversal: action first, feeling maybe later, maybe not. Choose one action tied to a value and schedule it for a specific time with no requirement to want to do it. Afterward the client records whether any wanting showed up during or after. Often it does, a little, and that is enough to build on.', '[{"id": "f0", "type": "textarea", "label": "The thing I am waiting to feel like doing, and how long I have waited:"}, {"id": "f1", "type": "textarea", "label": "Everything the rule I will do it when I feel like it has postponed:"}, {"id": "f2", "type": "textarea", "label": "The value the action serves:"}, {"id": "f3", "type": "textarea", "label": "The action, with a day and time, done whether or not I feel like it:"}, {"id": "f4", "type": "textarea", "label": "Afterward: did any wanting show up during or after? Describe it:"}, {"id": "f5", "type": "textarea", "label": "What this suggests about the order of action and feeling for me:"}]'::jsonb, array['depression', 'core ACT', 'committed action', 'values']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('photo-of-one-good-thing-daily-card', 'Photo of One Good Thing Daily Card', 'dbt'::resource_kind, 'A card for taking one photo a day of a small good thing and looking at the week''s photos together as accumulated positives.', 'Use it to give a client a short daily positive that produces evidence they can scroll back through.', array['Adults', 'Teens']::text[], 'One minute daily for two weeks', 'The task is one photo a day of anything that was even slightly good: a cup of coffee, a patch of light, a dog. The card asks for a caption of three words. In session, scroll through the two weeks together and ask the client to narrate. Clients with low mood tend to believe nothing good happened; the camera roll disagrees in their own hand. Watch for the client skipping days because nothing was good enough; the standard is slightly good, not good.', '[{"id": "f0", "type": "textarea", "label": "Today''s photo, and three words for it:"}, {"id": "f1", "type": "textarea", "label": "Days I skipped, and what I told myself about why:"}, {"id": "f2", "type": "textarea", "label": "Looking back at the week''s photos, the one that surprises me:"}, {"id": "f3", "type": "textarea", "label": "A pattern in what I chose to photograph:"}, {"id": "f4", "type": "textarea", "label": "What I notice in my body scrolling through the photos:"}]'::jsonb, array['depression', 'core DBT', 'accumulating positives', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('sunshine-spots-window-sticker-chart-craft', 'Sunshine Spots Window Sticker Chart Craft', 'kids'::resource_kind, 'A craft where the child makes a window chart and adds a sun sticker for each small good moment, with the parent asking what it was.', 'Use it to help a child with a heavy mood collect good moments where the light will catch them.', array['Children']::text[], '20 minutes to make, then daily', 'The child decorates a sheet of clear or tracing paper for the window and gets a strip of sun stickers. Each evening the parent asks for one moment that was a little bit good, and the child puts up a sun and says what it was. The parent does not add suns for the child or argue about whether a day had one; a tiny moment counts. After two weeks, count the suns together in the morning light and talk about what kinds of moments made the chart.', '[{"id": "f0", "type": "textarea", "label": "Today''s sun: the small good moment it stands for:"}, {"id": "f1", "type": "textarea", "label": "The kind of moment that gets a sun most often:"}, {"id": "f2", "type": "textarea", "label": "A day it was hard to find a sun, and the one we found anyway:"}, {"id": "f3", "type": "textarea", "label": "How many suns are on my window now:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what the chart has shown me about my child''s days:"}]'::jsonb, array['depression', 'children', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('task-dice-roll-and-do-group-game', 'Task Dice Roll and Do Group Game', 'game'::resource_kind, 'A game where each face of a die is a tiny task and players roll, do the task on the spot, and rate how it felt before and after.', 'Use it to show a group how small actions shift mood by doing six of them inside half an hour.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'The group assigns one tiny task to each die face before playing: stand and stretch, text someone hello, tidy one thing, drink a glass of water, step outside for thirty seconds, write one line of a list. Players take turns rolling and doing the task immediately, rating mood zero to ten before and after. Everyone rolls at least twice. Debrief: which tasks moved the number most, which felt pointless and still moved it, and which the player will keep.', '[{"id": "f0", "type": "textarea", "label": "The six tasks our group put on the die:"}, {"id": "f1", "type": "textarea", "label": "My rolls, with my mood before and after each one:"}, {"id": "f2", "type": "textarea", "label": "The task that moved my number most, even if I expected nothing:"}, {"id": "f3", "type": "textarea", "label": "The task that felt most pointless beforehand:"}, {"id": "f4", "type": "textarea", "label": "One task I will keep rolling for at home this week:"}]'::jsonb, array['depression', 'game', 'behavioral activation', 'group']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('interest-spark-inventory-for-boring-tasks', 'Interest Spark Inventory for Boring Tasks', 'worksheet'::resource_kind, 'An inventory of what makes a task interesting enough to start, matched to the client''s most avoided chores.', 'Use it to find the novelty, challenge, urgency or company a client needs before adding any of it to a dull task.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list five tasks they can start without effort and five they cannot, then look for what the easy ones share: a deadline, a timer, someone nearby, music, a competition, a reward, a change of place. Those are their sparks. Now add one spark to one boring task and try it before next session. Watch for the belief that needing a spark is a character flaw; everyone has them, and this is just a list of the client''s.', '[{"id": "f0", "type": "textarea", "label": "Five tasks I can start easily, and what they have in common:"}, {"id": "f1", "type": "textarea", "label": "Five tasks I cannot start, and what they have in common:"}, {"id": "f2", "type": "textarea", "label": "My sparks: the conditions that get me going (deadline, timer, company, music, place, challenge, reward):"}, {"id": "f3", "type": "textarea", "label": "The boring task I will attach one spark to this week, and which spark:"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried it:"}]'::jsonb, array['ADHD', 'motivation', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('i-work-better-under-pressure-belief-test-sheet', 'I Work Better Under Pressure Belief Test Sheet', 'cbt'::resource_kind, 'A sheet testing the belief that last-minute pressure produces the client''s best work by comparing rushed and early efforts.', 'Use it to let a client check a belief that keeps them starting everything the night before.', array['Adults', 'Teens']::text[], 'Two weeks', 'Rate the belief first. Then pick two comparable tasks: one done the usual way, one started early with a fake deadline and a timer. For each, the client records the quality of the result, the hours of stress, the sleep lost and what else got dropped. The comparison is rarely as clean as the belief claims; pressure may produce a result, but the sheet makes the full bill visible. Re-rate the belief afterward and keep the sheet for the next deadline.', '[{"id": "f0", "type": "textarea", "label": "The belief, and how much I believe it, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "Task one, done the usual way: result quality, stress hours, sleep lost, what else was dropped:"}, {"id": "f2", "type": "textarea", "label": "Task two, started early with a fake deadline: the same four things:"}, {"id": "f3", "type": "textarea", "label": "What the pressure actually gave me, and what it cost:"}, {"id": "f4", "type": "textarea", "label": "How much I believe it now:"}]'::jsonb, array['ADHD', 'core CBT', 'procrastination', 'behavioral experiment']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('urge-to-interrupt-surfing-card', 'Urge to Interrupt Surfing Card', 'dbt'::resource_kind, 'A card for riding the urge to jump into a conversation, with a holding move and a note to catch the thought.', 'Use it to give a client a way to hold a thought for thirty seconds without losing it or blurting it.', array['Adults', 'Teens']::text[], 'Five minutes to learn, then in conversations', 'The urge to interrupt is often the fear of losing the thought. The card offers a holding move: press a thumb into a fingertip, jot one word if a pen is near, and keep eyes on the speaker. Then the urge is treated like any other, watched until it crests. Practice in session by having the client hold a thought for a minute while you talk. Log conversations where the card was used, how many thoughts were held, and how many were still there when the turn came.', '[{"id": "f0", "type": "textarea", "label": "The conversation, and how many urges to interrupt I noticed:"}, {"id": "f1", "type": "textarea", "label": "The holding move I used, and the one-word notes I made:"}, {"id": "f2", "type": "textarea", "label": "How many held thoughts were still there when my turn came:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the other person while I waited:"}, {"id": "f4", "type": "textarea", "label": "The urge that got through anyway, and what I did next:"}]'::jsonb, array['ADHD', 'core DBT', 'distress tolerance', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('parallel-admin-hour-for-partners-sheet', 'Parallel Admin Hour for Partners Sheet', 'couples'::resource_kind, 'A plan for a weekly hour where both partners sit together and do their own paperwork, bills and emails side by side.', 'Use it to give a couple a body-doubling hour that gets admin done without one partner nagging the other.', array['Couples']::text[], 'One hour weekly', 'Many couples fight about admin because one partner cannot start it alone. Set a weekly hour at the same time, same table, phones face down, each with their own pile. The partner who finds starting easy goes first and narrates nothing. The other partner lists their three items before the hour starts. Snacks help. Review after three weeks: what got done, what still stalls, and whether the hour needs to move. The point is company, not supervision.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my three admin items for this week''s hour:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my three admin items for this week''s hour:"}, {"id": "f2", "type": "textarea", "label": "Our hour: day, time, place, and the rule about phones:"}, {"id": "f3", "type": "textarea", "label": "What each of us finished during the hour, and what did not get started:"}, {"id": "f4", "type": "textarea", "label": "Partner who starts easily: what I noticed myself wanting to say, and did not:"}, {"id": "f5", "type": "textarea", "label": "Partner who finds starting hard: what made the hour easier than doing it alone:"}]'::jsonb, array['ADHD', 'couples', 'planning', 'household']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('transition-warning-flag-craft', 'Transition Warning Flag Craft', 'kids'::resource_kind, 'A craft where the child makes small flags for five minutes, two minutes and now, and the parent uses them to signal changes of activity.', 'Use it to give a child who struggles with stopping a visible countdown they helped build.', array['Children']::text[], '30 minutes to make, then daily', 'The child decorates three flags on sticks or straws: a green five-minute flag, a yellow two-minute flag and a red now flag. The parent agrees to use the flags before every change that tends to blow up: screen off, leaving the park, bath time. The parent plants each flag in view and says what it means the first few times. The child can wave the red flag themselves when they are ready early. Keep a tally of smoother transitions and talk about which flag helps most.', '[{"id": "f0", "type": "textarea", "label": "My three flags and what each one means:"}, {"id": "f1", "type": "textarea", "label": "The changes we use the flags for:"}, {"id": "f2", "type": "textarea", "label": "A time I saw the yellow flag and started getting ready by myself:"}, {"id": "f3", "type": "textarea", "label": "The flag that helps me most:"}, {"id": "f4", "type": "textarea", "label": "Parent note: transitions this week that went more smoothly, and the one that did not:"}]'::jsonb, array['ADHD', 'children', 'transitions', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('overnight-urges-and-sleep-pattern-log', 'Overnight Urges and Sleep Pattern Log', 'worksheet'::resource_kind, 'A log of nighttime urges for substance use alongside bedtime, wake time and what happened in the hours before.', 'Use it to find the link between a client''s sleep and their late-night urges before planning around either.', array['Adults']::text[], 'Two weeks', 'Many urges arrive after midnight, when the client is tired, alone and unobserved. For two weeks the client records bedtime, wake time, any urge with its time and strength, and what the evening held. In session, look for the shape: short sleep followed by urge nights, or evenings that ran late with nothing planned. Build the plan from the pattern, whether that is an earlier wind-down or a call at the usual urge hour. Never use the log to shame a slip; it is weather data.', '[{"id": "f0", "type": "textarea", "label": "Each night: when I went to bed, when I woke, and how rested I felt:"}, {"id": "f1", "type": "textarea", "label": "Urges that came after dark: the time, strength zero to ten, and what I was doing:"}, {"id": "f2", "type": "textarea", "label": "What the evening before an urge night tended to hold:"}, {"id": "f3", "type": "textarea", "label": "What I did with each urge, and how long it lasted:"}, {"id": "f4", "type": "textarea", "label": "The pattern I see, and one change to the evening I am willing to try:"}]'::jsonb, array['addiction', 'sleep', 'self-monitoring', 'urges']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('i-can-be-around-it-now-belief-check-sheet', 'I Can Be Around It Now Belief Check Sheet', 'cbt'::resource_kind, 'A sheet examining the belief that the client can safely be around substance use now, with the evidence each way and a smaller test.', 'Use it to slow down a confident decision to attend a risky event long enough to look at the record.', array['Adults']::text[], '25 minutes', 'This belief tends to arrive with good news: a few clear weeks and an invitation. Write the belief out and the prediction attached to it. Then list the times the client has been around substance use since they changed their pattern, and what happened each time. Weigh the evidence honestly, including the clear times. If the client still wants to attend, the sheet asks for a smaller version first and an exit plan. The clinician''s job is to make the decision slower, not to make it for them.', '[{"id": "f0", "type": "textarea", "label": "The belief and the event it is attached to:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen if I go:"}, {"id": "f2", "type": "textarea", "label": "Times I have been around it since I changed my pattern, and what happened each time:"}, {"id": "f3", "type": "textarea", "label": "Evidence that I can be around it, and evidence that I cannot yet:"}, {"id": "f4", "type": "textarea", "label": "A smaller version of the event I could test first:"}, {"id": "f5", "type": "textarea", "label": "If I go: my exit plan and who knows about it:"}]'::jsonb, array['addiction', 'core CBT', 'relapse prevention', 'urges']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('social-invitation-values-compass-page', 'Social Invitation Values Compass Page', 'act'::resource_kind, 'A page for weighing an invitation to a drinking or using event against the client''s values and deciding on purpose.', 'Use it to turn each risky invitation into a values choice rather than a willpower contest.', array['Adults']::text[], '15 minutes per invitation', 'When an invitation arrives, the client writes what pulls them toward it and names the value under the pull, usually belonging or fun. Then they ask whether going serves that value as well as a different plan would. Three options get written: go with a plan, go to a modified version, or decline and meet the value another way. Any of the three can be right. Afterward, the client records which they chose and whether the value was served. Over time the stack shows what actually works.', '[{"id": "f0", "type": "textarea", "label": "The invitation, and what pulls me toward it:"}, {"id": "f1", "type": "textarea", "label": "The value underneath the pull:"}, {"id": "f2", "type": "textarea", "label": "Option one, go with a plan: what the plan is:"}, {"id": "f3", "type": "textarea", "label": "Option two, a modified version: what I would change:"}, {"id": "f4", "type": "textarea", "label": "Option three, decline and serve the value another way: what that way is:"}, {"id": "f5", "type": "textarea", "label": "What I chose, and afterward, whether the value was served:"}]'::jsonb, array['addiction', 'core ACT', 'values', 'urges']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('substance-free-evenings-together-planner-for-partners', 'Substance-Free Evenings Together Planner for Partners', 'couples'::resource_kind, 'A planner for partners to design evenings they both enjoy that do not revolve around substance use, with each partner''s picks.', 'Use it to help a couple rebuild shared evenings when the old ones are no longer on the table.', array['Couples']::text[], '45 minutes, then weekly', 'Couples often discover that most of their fun was built around using. Each partner lists evenings they enjoyed before the pattern took over and new things they would try. They pick two for the week and plan the details: time, place, cost, what to do if an urge shows up. The supporting partner names what they will not do, such as monitoring. Review weekly and keep the evenings that worked. Watch for one partner carrying all the planning.', '[{"id": "f0", "type": "textarea", "label": "Partner A: evenings I enjoyed before, and new things I would try:"}, {"id": "f1", "type": "textarea", "label": "Partner B: evenings I enjoyed before, and new things I would try:"}, {"id": "f2", "type": "textarea", "label": "The two evenings we will do this week, with time, place and cost:"}, {"id": "f3", "type": "textarea", "label": "Partner with the substance use pattern: what I will do if an urge shows up during the evening:"}, {"id": "f4", "type": "textarea", "label": "Supporting partner: what I will do, and what I will not do, that evening:"}, {"id": "f5", "type": "textarea", "label": "After the week: which evening we will keep, and why:"}]'::jsonb, array['addiction', 'couples', 'connection', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('pass-or-play-urge-scenario-card-game', 'Pass or Play Urge Scenario Card Game', 'game'::resource_kind, 'A card game where players draw an urge scenario and choose pass, naming an exit, or play, naming a skill, then the group votes.', 'Use it to let a group rehearse quick decisions about substance use situations before they face the real ones.', array['Groups', 'Adults']::text[], '40 minutes', 'Prepare scenario cards: an old friend texts, a work party with an open bar, a bad day and an empty apartment, a wedding toast. On a turn the player reads the card and says pass, meaning they would leave or avoid and how, or play, meaning they would stay and the skill they would use. The group votes on whether the plan would hold. Points for plans the group believes. Debrief on which scenarios split the group and which skills came up most.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew, and whether I chose pass or play:"}, {"id": "f1", "type": "textarea", "label": "My plan in one or two sentences:"}, {"id": "f2", "type": "textarea", "label": "What the group said about whether it would hold:"}, {"id": "f3", "type": "textarea", "label": "The scenario that split the group, and why:"}, {"id": "f4", "type": "textarea", "label": "The skill that came up most often, and whether I actually have it ready:"}]'::jsonb, array['addiction', 'game', 'urges', 'group']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('anger-rules-i-did-not-choose-noticing-page', 'Anger Rules I Did Not Choose Noticing Page', 'act'::resource_kind, 'A page for noticing the rigid rules that set off anger, such as people must be on time, and holding them more lightly.', 'Use it to help a client see the rulebook their anger enforces and decide which rules they actually want.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to recall three recent flashes of anger and finish the sentence people should for each. The rules are usually reasonable preferences hardened into laws. Write them out as laws, then ask where each came from and whether the client would choose it today. The practice is not to drop the preference but to hold it as a preference: I would prefer, rather than they must. Rehearse saying one rule in the softer form when it is next broken.', '[{"id": "f0", "type": "textarea", "label": "Three recent flashes of anger, and the people should sentence for each:"}, {"id": "f1", "type": "textarea", "label": "Where each rule came from, as best I can tell:"}, {"id": "f2", "type": "textarea", "label": "Which rules I would choose today, and which I inherited:"}, {"id": "f3", "type": "textarea", "label": "Each rule rewritten as a preference, in the form I would prefer:"}, {"id": "f4", "type": "textarea", "label": "The rule most likely to be broken this week, and what I will say to myself when it is:"}]'::jsonb, array['anger management', 'core ACT', 'defusion', 'values']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('gently-avoid-opposite-action-for-anger-card', 'Gently Avoid Opposite Action for Anger Card', 'dbt'::resource_kind, 'A card for the opposite action to anger: stepping away kindly, with a return time, instead of attacking or stonewalling.', 'Use it to give a client a way to leave a heated moment that does not read as punishment.', array['Adults', 'Teens']::text[], 'Ten minutes to learn, then as needed', 'Opposite action for anger has two halves: gently avoid the person, and do something kind or at least neutral toward them in your head. The card scripts the exit: a soft sentence, a stated return time, and a cooling task for the gap. Rehearse the sentence until it sounds like the client. The return time is what separates this from stonewalling. Log each use, whether the client came back on time, and what they were thinking about the person while away.', '[{"id": "f0", "type": "textarea", "label": "My exit sentence, in my own words, with a return time:"}, {"id": "f1", "type": "textarea", "label": "What I will do during the gap to cool down:"}, {"id": "f2", "type": "textarea", "label": "What I will try to think about the person while I am away:"}, {"id": "f3", "type": "textarea", "label": "Each time I used it: did I come back when I said, and how did the return go?"}, {"id": "f4", "type": "textarea", "label": "A time I wanted to use it and did not, and what stopped me:"}]'::jsonb, array['anger management', 'core DBT', 'opposite action', 'emotion regulation']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('argument-rematch-scheduling-sheet-for-partners', 'Argument Rematch Scheduling Sheet for Partners', 'couples'::resource_kind, 'A sheet for partners to schedule a return to an argument they paused, with a time, a place and each partner''s one goal.', 'Use it to make sure a paused fight gets finished calmly rather than dropped or restarted hot.', array['Couples']::text[], '20 minutes', 'Pausing a fight only works if the couple comes back to it. When either partner calls a pause, they fill in this sheet together before separating: the topic in one neutral sentence, a return time within twenty-four hours, a place, and one thing each wants from the rematch. At the rematch, each partner opens with the other''s goal. Review how many pauses turned into rematches this month and what happened to the ones that did not.', '[{"id": "f0", "type": "textarea", "label": "The topic we paused, in one sentence we both accept:"}, {"id": "f1", "type": "textarea", "label": "When and where we will return to it (within twenty-four hours):"}, {"id": "f2", "type": "textarea", "label": "Partner A: the one thing I want from the rematch:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the one thing I want from the rematch:"}, {"id": "f4", "type": "textarea", "label": "At the rematch: how each of us opened, and how it went:"}, {"id": "f5", "type": "textarea", "label": "Pauses this month that never got a rematch, and what happened to them:"}]'::jsonb, array['anger management', 'couples', 'conflict', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('cool-down-countdown-paper-chain-craft', 'Cool Down Countdown Paper Chain Craft', 'kids'::resource_kind, 'A craft where the child makes a paper chain with one cool-down step per link and tears off a link at a time while calming down.', 'Use it to give a child a cool-down sequence they can see and feel shortening.', array['Children']::text[], '30 minutes to make, then as needed', 'The child and parent write or draw one calming step on each strip: take three breaths, squeeze a pillow, get a drink, count to ten, tell someone how I feel. Loop the strips into a chain and hang it low. When the child is getting hot, the parent points to the chain and the child tears off a link, does the step, then the next. Make several chains so there is always a fresh one. The parent does not tear the links for the child or rush them.', '[{"id": "f0", "type": "textarea", "label": "The steps on my chain, in order:"}, {"id": "f1", "type": "textarea", "label": "A time I tore off links this week, and how many it took:"}, {"id": "f2", "type": "textarea", "label": "The step that works best for me:"}, {"id": "f3", "type": "textarea", "label": "A step I want to add to the next chain:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what I did while my child worked down the chain:"}]'::jsonb, array['anger management', 'children', 'coping skills', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('keep-your-cool-provocation-cards-game', 'Keep Your Cool Provocation Cards Game', 'game'::resource_kind, 'A group game where a player draws a mild provocation card, hears it read aloud, and must respond calmly inside ten seconds.', 'Use it to let a group rehearse calm replies to the comments that usually set them off.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'The group writes mild provocations on cards first, agreeing nothing personal or cruel: you are late again, that is a stupid idea, whatever. On a turn, another player reads a card in a flat voice and the player has ten seconds to give a calm reply or to use a pause move out loud. The group rates the reply for calm, one to five. Rotate until everyone has had three turns. Debrief which cards hit hardest, which replies the group rated highest, and what a pause move looks like in real life.', '[{"id": "f0", "type": "textarea", "label": "The provocation that hit me hardest, and what I felt in my body:"}, {"id": "f1", "type": "textarea", "label": "My calmest reply, and what the group rated it:"}, {"id": "f2", "type": "textarea", "label": "The pause move I used, or wish I had used:"}, {"id": "f3", "type": "textarea", "label": "A reply someone else gave that I want to borrow:"}, {"id": "f4", "type": "textarea", "label": "The real-life comment this game was closest to, and my plan for it:"}]'::jsonb, array['anger management', 'game', 'group', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('unlucky-numbers-words-and-colors-inventory', 'Unlucky Numbers Words and Colors Inventory', 'worksheet'::resource_kind, 'An inventory of the numbers, words, colors and phrases a client avoids or must balance, with what each costs in a week.', 'Use it to map magical avoidance before any practice, so the client and clinician see the whole set.', array['Adults', 'Teens']::text[], '30 minutes', 'Some clients steer around a number on the clock, a word in conversation, or a color in a store without anyone knowing. List every item, what the client does to avoid or neutralize it, and how many times a week it comes up. Ask what the item is believed to cause. Clients are often embarrassed; keep the tone matter-of-fact and note that the list is for planning only. Rank the items by how much daily life they shape, not by how strange they feel.', '[{"id": "f0", "type": "textarea", "label": "Numbers, words, colors or phrases I avoid or have to balance out:"}, {"id": "f1", "type": "textarea", "label": "What I do when one shows up (avoid, repeat, undo, say something else):"}, {"id": "f2", "type": "textarea", "label": "What I believe each one could cause if I let it stand:"}, {"id": "f3", "type": "textarea", "label": "Roughly how many times a week each one comes up:"}, {"id": "f4", "type": "textarea", "label": "The one that shapes my day most, and what my day would hold without it:"}]'::jsonb, array['OCD', 'avoidance', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('thinking-it-makes-it-happen-experiment-sheet', 'Thinking It Makes It Happen Experiment Sheet', 'cbt'::resource_kind, 'A sheet for testing the belief that a thought can cause an event by deliberately thinking a harmless one and watching the outcome.', 'Use it to let a client collect their own evidence about whether thoughts have power over events.', array['Adults', 'Teens']::text[], 'One week', 'Choose a low-stakes target with the client: thinking hard that the clinician will trip on the way to the door, that a specific light bulb will burn out tonight, that it will rain at noon. The client writes the prediction, thinks the thought on purpose several times a day, and records what happened. Start with targets that carry no dread so the method is clear before anything touches the feared themes. Discuss why the mind treats some thoughts as more powerful than others.', '[{"id": "f0", "type": "textarea", "label": "The belief: thinking something makes it more likely to happen. How much I believe it, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "The harmless event I will try to cause by thinking it, and my prediction:"}, {"id": "f2", "type": "textarea", "label": "How many times a day I thought it on purpose, and what it felt like to try:"}, {"id": "f3", "type": "textarea", "label": "What actually happened each day:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about the belief, and how much I believe it now:"}]'::jsonb, array['OCD', 'core CBT', 'behavioral experiment', 'intrusive thoughts']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('participate-in-the-messy-moment-card', 'Participate in the Messy Moment Card', 'dbt'::resource_kind, 'A card for throwing oneself fully into an activity while something is out of place, instead of standing apart to fix or check.', 'Use it to give a client a way to stay in the moment with a not-right feeling present, using the DBT skill of participating.', array['Adults', 'Teens']::text[], 'Ten minutes, as needed', 'Participating means entering the activity with the whole self. For a client pulled by a crooked frame or an unchecked lock, the card says: notice the pull, name it, then put both hands and full attention into the task at hand, whether that is cooking, a conversation or a game. The pull stays present and unanswered. Practice in session with a deliberately misaligned object on the desk. Log where it was used and how long until the pull faded on its own.', '[{"id": "f0", "type": "textarea", "label": "The out-of-place thing, and how strong the pull was, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "The activity I threw myself into instead:"}, {"id": "f2", "type": "textarea", "label": "What it felt like to participate with the pull still there:"}, {"id": "f3", "type": "textarea", "label": "How long until the pull faded without my doing anything about it:"}, {"id": "f4", "type": "textarea", "label": "A moment this week I want to try it again:"}]'::jsonb, array['OCD', 'core DBT', 'mindfulness', 'ritual delay']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('doubt-dragon-puppet-craft', 'Doubt Dragon Puppet Craft', 'kids'::resource_kind, 'A craft where the child makes a puppet for the voice that says are you sure and practices answering it with maybe, parent playing along.', 'Use it to give a child and parent a shared, playful way to talk back to doubt without checking.', array['Children']::text[], '40 minutes to make, then play', 'The child builds a dragon puppet from a sock or paper bag and gives it a name. The parent voices the dragon asking are you sure, did you really, what if, and the child answers with maybe, I do not know, or let us find out later, and goes on with what they were doing. Swap roles so the child voices the dragon too. Keep it silly. The parent agrees not to answer the dragon''s questions for the child in daily life, but to ask what the child would tell the dragon.', '[{"id": "f0", "type": "textarea", "label": "My dragon''s name and what it looks like:"}, {"id": "f1", "type": "textarea", "label": "The things my dragon asks over and over:"}, {"id": "f2", "type": "textarea", "label": "My favorite answers to the dragon:"}, {"id": "f3", "type": "textarea", "label": "A time this week the dragon showed up without the puppet, and what I said:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what I say now instead of answering the dragon''s questions:"}]'::jsonb, array['OCD', 'children', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('leave-it-crooked-challenge-game', 'Leave It Crooked Challenge Game', 'game'::resource_kind, 'A group game where players deliberately set objects slightly wrong and earn points for every minute they leave them, with a debrief.', 'Use it to let a group practice tolerating not-just-right feelings together, with humor and a timer.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Each player picks an object in the room and sets it slightly wrong: a tilted picture, a pen off the line, a chair askew. A timer runs for fifteen minutes while the group does an ordinary activity. Players earn a point per minute their object stays crooked and lose all points if they fix it. Players call out their discomfort rating every five minutes. Debrief on how the ratings moved, who fixed and why, and where in life the same urge shows up.', '[{"id": "f0", "type": "textarea", "label": "The object I set wrong, and my discomfort rating at the start:"}, {"id": "f1", "type": "textarea", "label": "My ratings at five, ten and fifteen minutes:"}, {"id": "f2", "type": "textarea", "label": "Whether I fixed it, and what was happening right before if I did:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about other players'' objects while mine stayed crooked:"}, {"id": "f4", "type": "textarea", "label": "Where this urge shows up at home, and one thing I might leave crooked there:"}]'::jsonb, array['OCD', 'game', 'group', 'uncertainty']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('what-did-not-happen-panic-ledger', 'What Did Not Happen Panic Ledger', 'worksheet'::resource_kind, 'A running ledger of every panic surge, the catastrophe the client expected during it, and what actually followed.', 'Use it to build a record the client can read the next time the body insists this one is different.', array['Adults', 'Teens']::text[], 'Ongoing for a month', 'For each surge the client writes the date, the peak feared outcome in the moment, such as I will pass out or my heart will give out, and what happened in the following hour. Over a month the right-hand column fills with the same few words. Review it in session and have the client read it aloud. The ledger is not meant to argue with the fear during a surge; it is meant to be there afterward, in the client''s own handwriting.', '[{"id": "f0", "type": "textarea", "label": "Date and where I was when the surge hit:"}, {"id": "f1", "type": "textarea", "label": "What I was sure was about to happen at the peak:"}, {"id": "f2", "type": "textarea", "label": "What actually happened in the next hour:"}, {"id": "f3", "type": "textarea", "label": "How long the peak lasted:"}, {"id": "f4", "type": "textarea", "label": "Reading the whole ledger: what the right-hand column says, in my own words:"}]'::jsonb, array['panic attacks', 'self-monitoring', 'thinking traps']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('spotlight-on-the-body-attention-experiment-sheet', 'Spotlight on the Body Attention Experiment Sheet', 'cbt'::resource_kind, 'An in-session experiment comparing two minutes of attention on the heartbeat with two minutes on the room, with sensation ratings.', 'Use it to show a client how attention alone turns up the volume on body sensations.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Rate sensations zero to ten. Have the client spend two minutes attending only to their heartbeat and breathing, then rate again. After a minute''s break, two minutes describing the room in detail, then rate again. Most clients find the inward minutes produced sensations the outward minutes did not. Talk through what that means for a day spent scanning the chest. Repeat at home with the sheet and compare the numbers.', '[{"id": "f0", "type": "textarea", "label": "My sensation ratings before we started:"}, {"id": "f1", "type": "textarea", "label": "Two minutes on my heartbeat and breath: what I noticed, and my ratings after:"}, {"id": "f2", "type": "textarea", "label": "Two minutes describing the room: what I noticed, and my ratings after:"}, {"id": "f3", "type": "textarea", "label": "What the difference tells me about where my attention goes during a scary day:"}, {"id": "f4", "type": "textarea", "label": "A time this week I caught myself in the inward spotlight and what I did:"}]'::jsonb, array['panic attacks', 'core CBT', 'behavioral experiment', 'attention']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('stay-in-the-store-willingness-steps-page', 'Stay in the Store Willingness Steps Page', 'act'::resource_kind, 'A page planning a graded return to a store the client flees from, with a willingness rating and a valued reason for each step.', 'Use it to help a client stay in a feared public place a little longer each time, on purpose and for a reason they chose.', array['Adults', 'Teens']::text[], 'Two weeks', 'Pick the store or venue the client leaves early. Write the valued reason for being able to shop there at all: feeding the family, independence, not asking others. Build four steps from standing inside the door for one minute to a full shopping trip, each with a willingness rating. The client goes when the rating is six or above and stays the planned time whether or not sensations arrive. Record what showed up and what the client did with it.', '[{"id": "f0", "type": "textarea", "label": "The place I leave early, and why I want to be able to stay:"}, {"id": "f1", "type": "textarea", "label": "Step one, and my willingness to do it, zero to ten:"}, {"id": "f2", "type": "textarea", "label": "Steps two, three and four, each with a willingness rating:"}, {"id": "f3", "type": "textarea", "label": "What showed up in my body during each step, and what I did with it:"}, {"id": "f4", "type": "textarea", "label": "The step I will do this week, and what would make it worth it:"}]'::jsonb, array['panic attacks', 'core ACT', 'willingness', 'exposure']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('panic-phone-call-script-for-partners', 'Panic Phone Call Script for Partners', 'couples'::resource_kind, 'A short script for what the supporting partner says when the other calls mid-surge, and what the panicking partner asks for.', 'Use it to make the panic call helpful and brief instead of a long reassurance loop.', array['Couples']::text[], '20 minutes', 'Write the script together. The partner who panics says what they want to hear in the first ten seconds, usually a calm voice and a reminder of what they already know. The supporting partner practices three sentences and a question that points outward: what can you see right now? Agree on a length for the call, usually three to five minutes, and what happens after it ends. Role play it twice in session. Review after the first real use and edit.', '[{"id": "f0", "type": "textarea", "label": "Partner who panics: what I want to hear in the first ten seconds:"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: my three sentences, in my own words:"}, {"id": "f2", "type": "textarea", "label": "The outward question the supporting partner will ask:"}, {"id": "f3", "type": "textarea", "label": "How long the call lasts, and what each of us does after it ends:"}, {"id": "f4", "type": "textarea", "label": "After the first real call: what helped, what did not, and the edit we made:"}]'::jsonb, array['panic attacks', 'couples', 'support', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('slow-down-snail-breathing-trail-craft', 'Slow Down Snail Breathing Trail Craft', 'kids'::resource_kind, 'A craft where the child draws a snail with a long spiral shell and traces the spiral slowly with a finger while breathing out.', 'Use it to teach a child a long slow exhale for a racing heart with a picture they made themselves.', array['Children']::text[], '20 minutes to make, then as needed', 'The child draws a big snail and colors the shell as one long spiral. The parent shows how to breathe in at the outside edge and breathe out slowly while tracing the spiral all the way to the center, so the out-breath lasts as long as the trail. Practice when calm and give the snail a name. When the child''s heart is racing, the parent hands them the snail and traces along with them. Laminate it or keep a copy in the car.', '[{"id": "f0", "type": "textarea", "label": "My snail''s name and the colors of its shell:"}, {"id": "f1", "type": "textarea", "label": "How many spirals I can trace before I need to breathe in again:"}, {"id": "f2", "type": "textarea", "label": "A time my heart was racing and I used the snail:"}, {"id": "f3", "type": "textarea", "label": "How my body felt at the center of the spiral:"}, {"id": "f4", "type": "textarea", "label": "Parent note: where we keep the snail and when it has helped:"}]'::jsonb, array['panic attacks', 'children', 'breathing', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('my-child-is-doing-this-to-me-thought-check-sheet', 'My Child Is Doing This to Me Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for examining the thought that a child''s behavior is aimed at the parent, with other explanations and a test.', 'Use it to help a parent separate what a child did from what the parent decided it meant.', array['Adults']::text[], '25 minutes', 'Parents often read a child''s behavior as deliberate and personal: he is doing this to push me. Write the behavior as a camera would record it, then the parent''s thought, then at least three other explanations: tired, hungry, overwhelmed, testing a limit, copying a peer. Ask what the parent would do differently under each explanation. Then choose one to test this week by responding as if it were true and watching what happens.', '[{"id": "f0", "type": "textarea", "label": "What my child did, described the way a camera would record it:"}, {"id": "f1", "type": "textarea", "label": "The thought I had about why:"}, {"id": "f2", "type": "textarea", "label": "Three other explanations, even ones I doubt:"}, {"id": "f3", "type": "textarea", "label": "What I would do under each explanation:"}, {"id": "f4", "type": "textarea", "label": "The explanation I will act on this week as a test, and what I noticed:"}]'::jsonb, array['parenting', 'core CBT', 'thinking traps']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-in-the-store-meltdown-card', 'Nonjudgmental Stance in the Store Meltdown Card', 'dbt'::resource_kind, 'A card for the public tantrum: describing what is happening without judgment words, for the child and for the parent themselves.', 'Use it to give a parent a mindfulness move for the moment strangers are watching.', array['Adults']::text[], 'Five minutes to learn, then as needed', 'In a public meltdown parents judge twice: the child is being impossible, and I am a terrible parent. The card replaces both with description. My child is on the floor crying and kicking. I am standing here with a hot face and a tight chest. People are looking. Then one effective action. Rehearse the descriptions in session with a recent scene. The judgments will come back; the skill is noticing and describing again. Log each use and the action that followed.', '[{"id": "f0", "type": "textarea", "label": "The scene, described without judgment words:"}, {"id": "f1", "type": "textarea", "label": "What was happening in my body, described the same way:"}, {"id": "f2", "type": "textarea", "label": "The judgments that showed up anyway, about my child and about me:"}, {"id": "f3", "type": "textarea", "label": "The one effective action I took next:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the rest of the outing:"}]'::jsonb, array['parenting', 'core DBT', 'mindfulness', 'nonjudgmental stance']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('parenting-style-differences-bridge-sheet', 'Parenting Style Differences Bridge Sheet', 'couples'::resource_kind, 'A sheet where co-parents name where their approaches differ, what each fears the other''s style will cause, and one shared rule per gap.', 'Use it to turn a running argument about strict versus soft into a short list of rules both parents own.', array['Couples']::text[], 'Full session', 'Each parent lists the three situations where the other''s parenting bothers them most and the fear under it, such as if we give in now she will never listen. Read them aloud without rebuttal. Then for each situation, write one rule both can follow in front of the child, even if neither would have chosen it alone. Agree to argue about the rule later, never in the moment. Watch for one parent folding to end the session; both names go on every rule.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three situations where your approach worries me, and the fear under each:"}, {"id": "f1", "type": "textarea", "label": "Partner B: three situations where your approach worries me, and the fear under each:"}, {"id": "f2", "type": "textarea", "label": "What each of us heard in the other''s fears that we had not understood:"}, {"id": "f3", "type": "textarea", "label": "One shared rule for each situation, written so both of us can say it:"}, {"id": "f4", "type": "textarea", "label": "Where and when we will argue about a rule if it is not working:"}, {"id": "f5", "type": "textarea", "label": "The first rule we will use this week:"}]'::jsonb, array['parenting', 'couples', 'co-parenting', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('family-calm-corner-sign-and-rules-craft', 'Family Calm Corner Sign and Rules Craft', 'kids'::resource_kind, 'A craft where the child makes the sign and the three rules for the family''s calm corner, which any family member may use.', 'Use it to make a calm space feel like the child''s idea and to let the child see parents use it too.', array['Children']::text[], '30 minutes', 'The child paints the sign and chooses three rules for the corner, with the parent''s help: one person at a time, nobody follows you in unless asked, you come out when you are ready. The parent agrees to use the corner themselves at least once this week in front of the child and to say so: I need the calm corner for a minute. The corner is never a punishment and is never assigned. Talk afterward about who used it and what happened.', '[{"id": "f0", "type": "textarea", "label": "What my sign says and looks like:"}, {"id": "f1", "type": "textarea", "label": "Our three calm corner rules:"}, {"id": "f2", "type": "textarea", "label": "A time I went to the corner this week, and how long I stayed:"}, {"id": "f3", "type": "textarea", "label": "A time I saw a grown-up use the corner:"}, {"id": "f4", "type": "textarea", "label": "Parent note: how it went when I used the corner in front of my child:"}]'::jsonb, array['parenting', 'children', 'coping skills', 'family']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('praise-ping-pong-family-game', 'Praise Ping-Pong Family Game', 'game'::resource_kind, 'A quick family game where praise bounces between players, each one specific and about something from the last day.', 'Use it to get a family practicing specific praise in a fast, playful round at the table.', array['Children', 'Groups']::text[], '10 minutes', 'Sit in a circle. The first player serves a specific praise to someone: I noticed you put your shoes away without being asked. The receiver says thank you and serves to someone else. The ball drops if praise is vague, such as you are nice, and the round restarts. Play until everyone has received two. Parents play as equals and receive praise from children. Debrief on which praise was easiest to give, which was hardest to receive, and what the family noticed about each other.', '[{"id": "f0", "type": "textarea", "label": "A praise I served, and who it went to:"}, {"id": "f1", "type": "textarea", "label": "A praise I received, and how it felt to just say thank you:"}, {"id": "f2", "type": "textarea", "label": "A praise that dropped the ball, and how we made it specific:"}, {"id": "f3", "type": "textarea", "label": "The person it was hardest to find a specific praise for:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what my children praised in me that I had not noticed they saw:"}]'::jsonb, array['parenting', 'game', 'family', 'praise']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('birth-story-telling-pacing-sheet', 'Birth Story Telling Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for a new parent who wants to tell their birth story, choosing how much, to whom, and the stop signal.', 'Use it to let a client approach a hard birth story in session at a pace they set, without writing it out as homework.', array['Adults']::text[], 'In session, over several sessions', 'Some birth stories need telling and some clients are not ready. This sheet is for in-session use only. The client marks how much they want to tell today on a line from the headline to the full account, names who else they might tell and who they do not want to, and chooses a word that means stop. Pause for grounding whenever the client''s voice changes. The details are spoken, not written; the sheet records only how the telling went and what helped.', '[{"id": "f0", "type": "textarea", "label": "How much I want to tell today, from just the headline to the whole thing:"}, {"id": "f1", "type": "textarea", "label": "My stop word, and what I want you to do when I say it:"}, {"id": "f2", "type": "textarea", "label": "People I might want to tell some of this to, and people I do not:"}, {"id": "f3", "type": "textarea", "label": "After today: how it felt to tell what I told, and what helped:"}, {"id": "f4", "type": "textarea", "label": "What I want next time: more, the same, or a break from it:"}]'::jsonb, array['perinatal and postpartum', 'pacing', 'support']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('scary-thoughts-about-the-baby-defusion-page', 'Scary Thoughts About the Baby Defusion Page', 'act'::resource_kind, 'A page for the unwanted intrusive thoughts many new parents have, naming them as thoughts and returning attention to the baby in the room.', 'Use it to help a new parent hold a frightening thought as a thought rather than a sign or a wish.', array['Adults']::text[], 'In session, then brief daily practice', 'Complete this in session first. Many new parents have sudden images of harm coming to the baby and are terrified of what the thought means about them. Make room to hear the thought without flinching, name it as a thought, and practice the defusion line: I am having the thought that. Then attention goes to the baby''s actual breathing, weight, smell. Check safety directly and in your own words; a client afraid they might act on a thought, or who is thinking of harming themselves, needs 988 (call or text) and your plan, not a worksheet.', '[{"id": "f0", "type": "textarea", "label": "The kind of thought that shows up, in general terms, and how I feel about myself when it does:"}, {"id": "f1", "type": "textarea", "label": "The thought said as I am having the thought that:"}, {"id": "f2", "type": "textarea", "label": "What I notice about my baby right now with my senses:"}, {"id": "f3", "type": "textarea", "label": "What I did with the thought today instead of fighting it:"}, {"id": "f4", "type": "textarea", "label": "If I ever feel I might act on a thought or want to hurt myself, I will call or text 988 and tell:"}]'::jsonb, array['perinatal and postpartum', 'core ACT', 'defusion', 'intrusive thoughts']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('mindful-rocking-chair-minute-card', 'Mindful Rocking Chair Minute Card', 'dbt'::resource_kind, 'A card for one minute of mindfulness while rocking the baby, with attention on the rhythm, the weight and the breath.', 'Use it to give a new parent a mindfulness practice inside something they already do a dozen times a day.', array['Adults']::text[], 'One minute, several times daily', 'New parents have no spare minutes, so the practice lives in the rocking. The card says: feel the chair move, feel the baby''s weight on the chest, match the breath to the rock, and when the mind runs to the laundry or the fear, come back to the weight. One minute counts. Clients tend to add this as another thing to do right; frame it as noticing what is already happening. Log which rockings became mindful ones and what the mind ran to most.', '[{"id": "f0", "type": "textarea", "label": "When I rocked today, and which times I remembered the card:"}, {"id": "f1", "type": "textarea", "label": "What I felt: the rhythm, the weight, the breath:"}, {"id": "f2", "type": "textarea", "label": "Where my mind ran most often:"}, {"id": "f3", "type": "textarea", "label": "What it was like to come back to the weight:"}, {"id": "f4", "type": "textarea", "label": "One thing I noticed about my baby that I had been missing:"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'mindfulness', 'new parents']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('resentment-early-catch-talk-sheet-for-new-parents', 'Resentment Early Catch Talk Sheet for New Parents', 'couples'::resource_kind, 'A sheet for new parents to name a small resentment before it hardens, with the need under it and one trade.', 'Use it to give a couple a weekly way to clear the score before it becomes the story of the first year.', array['Couples']::text[], '20 minutes weekly', 'Resentment in the first year usually starts small: who slept, who got out of the house, whose work counts. Each partner writes one resentment from the week, rated one to ten, and the need under it. They read them to each other without defending. Then they agree on one trade for the coming week. Keep it to one each; the point is to catch early, not to empty the tank. Watch for the partner who insists they have none.', '[{"id": "f0", "type": "textarea", "label": "Partner A: one resentment from this week, rated one to ten, and the need under it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: one resentment from this week, rated one to ten, and the need under it:"}, {"id": "f2", "type": "textarea", "label": "What each of us heard in the other''s need:"}, {"id": "f3", "type": "textarea", "label": "The one trade we will make this week:"}, {"id": "f4", "type": "textarea", "label": "Next week: did the trade happen, and what changed in the rating?"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication', 'new parents']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('new-parent-myth-or-reality-card-game', 'New Parent Myth or Reality Card Game', 'game'::resource_kind, 'A group game where players sort statements about new parenthood into myth or reality and defend the call with their own experience.', 'Use it to let a new parent group loosen the shoulds they arrived with and hear each other''s real days.', array['Groups', 'Adults']::text[], '40 minutes', 'Prepare statements: you will feel love at first sight, good parents do not need breaks, the baby can tell when you are anxious, the house should be presentable for visitors. On a turn, a player draws one, calls myth or reality, and gives thirty seconds from their own week. The group votes and may disagree. No statement has a scored right answer; the points go to the most honest defense. Debrief on the statement that split the room and the should each person is putting down.', '[{"id": "f0", "type": "textarea", "label": "The statement I drew, and whether I called it myth or reality:"}, {"id": "f1", "type": "textarea", "label": "What I said from my own week to defend the call:"}, {"id": "f2", "type": "textarea", "label": "The statement that split the room, and the two sides:"}, {"id": "f3", "type": "textarea", "label": "A should I arrived with that this game loosened:"}, {"id": "f4", "type": "textarea", "label": "Something another parent said that I needed to hear:"}]'::jsonb, array['perinatal and postpartum', 'game', 'group', 'new parents']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('skills-i-taught-myself-inventory', 'Skills I Taught Myself Inventory', 'worksheet'::resource_kind, 'An inventory of everything the client learned without a teacher, from cooking an egg to fixing a bike, as evidence of capability.', 'Use it to show a client who feels incapable the record of things they figured out alone.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with the trivial and let it grow: tying shoes, driving, a phone''s settings, a recipe, a language, how to calm a friend. Ask how each was learned and what the client did when stuck. Clients who dismiss everyone can do that are missing the point; the list is not about rarity but about the pattern of a person who figures things out. End by applying that pattern to the thing they currently feel incapable of.', '[{"id": "f0", "type": "textarea", "label": "Things I learned without anyone teaching me, from small to large:"}, {"id": "f1", "type": "textarea", "label": "How I learned the three that mattered most, step by step:"}, {"id": "f2", "type": "textarea", "label": "What I did when I got stuck on each one:"}, {"id": "f3", "type": "textarea", "label": "The pattern I see in how I figure things out:"}, {"id": "f4", "type": "textarea", "label": "The thing I currently feel incapable of, and what the pattern suggests I would do first:"}]'::jsonb, array['self-esteem', 'strengths', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('labels-into-behaviors-translation-sheet', 'Labels Into Behaviors Translation Sheet', 'cbt'::resource_kind, 'A sheet for translating a global self-label, such as I am a failure, into the specific behaviors that are being judged.', 'Use it to shrink a label about the whole self down to the actions it was built from.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the label in the left column. In the right, list the actual behaviors the client is thinking of when they say it: I missed a deadline, I did not call back, I quit the class. Then ask whether each behavior, on its own, earns the label, and what a behavior is called that a person can change. Labels are permanent and behaviors are not. Close by rewriting the label as a sentence about behaviors and one behavior the client wants to change.', '[{"id": "f0", "type": "textarea", "label": "The label I put on myself, as I say it in my head:"}, {"id": "f1", "type": "textarea", "label": "The actual behaviors I am thinking of when I say it:"}, {"id": "f2", "type": "textarea", "label": "Does any one of those behaviors, alone, earn the label? Why or why not?"}, {"id": "f3", "type": "textarea", "label": "The label rewritten as a sentence about behaviors:"}, {"id": "f4", "type": "textarea", "label": "One behavior on the list I want to change, and the first step:"}]'::jsonb, array['self-esteem', 'core CBT', 'labeling', 'thinking traps']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('peeling-off-i-am-labels-defusion-page', 'Peeling Off I Am Labels Defusion Page', 'act'::resource_kind, 'A defusion page where the client writes each I am label on an imagined sticker, peels it off and sets it beside them.', 'Use it to give a client a physical sense of a label as something stuck on rather than something they are.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write their I am labels on actual sticky notes if possible and press each one to their sleeve. Then, one by one, peel it off, read it as a thought, and set it on the table where they can still see it. Ask what is left wearing the sleeve. The labels are not argued with or replaced; they are just not worn. Clients often laugh, which is useful. The page records the labels, where they came from, and what it was like to sit beside them instead of under them.', '[{"id": "f0", "type": "textarea", "label": "My I am labels, one per sticker:"}, {"id": "f1", "type": "textarea", "label": "Where each label was first stuck on me, as best I remember:"}, {"id": "f2", "type": "textarea", "label": "What it was like to peel one off and read it as a thought:"}, {"id": "f3", "type": "textarea", "label": "What was left when all the stickers were on the table:"}, {"id": "f4", "type": "textarea", "label": "The label I expect to find back on my sleeve tomorrow, and how I will peel it:"}]'::jsonb, array['self-esteem', 'core ACT', 'defusion', 'self-as-context']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('proud-pennant-banner-craft', 'Proud Pennant Banner Craft', 'kids'::resource_kind, 'A craft where the child makes a string of triangle pennants, one for each thing they are proud of, and hangs it with a parent.', 'Use it to give a child a visible, growing record of things they did that they are proud of.', array['Children']::text[], '30 minutes to start, then weekly', 'Cut triangles from paper or felt. On each, the child draws or writes one thing they did that they are proud of, as small as a brave hello or sharing a toy. The parent helps only with cutting and spelling, never with choosing; the child decides what counts. String the pennants and hang them. Each week add one. The parent points to the banner when the child says I cannot do anything. The sheet tracks the pennants and the stories behind them.', '[{"id": "f0", "type": "textarea", "label": "The pennants on my banner so far, and the story behind each:"}, {"id": "f1", "type": "textarea", "label": "This week''s new pennant:"}, {"id": "f2", "type": "textarea", "label": "The pennant I am proudest of:"}, {"id": "f3", "type": "textarea", "label": "A time my grown-up pointed at the banner, and what I remembered:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what my child chose to be proud of that I would not have guessed:"}]'::jsonb, array['self-esteem', 'children', 'strengths', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('compliment-telephone-chain-game', 'Compliment Telephone Chain Game', 'game'::resource_kind, 'A whisper game where a specific compliment about a group member passes down the line, with points for arriving intact.', 'Use it to get a group giving and receiving specific compliments with the pressure of being face to face removed.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'The first player whispers a specific compliment about the last player in line to the second player, and so on down the line. The last player hears it, says it aloud, and the first player reads the original. Points if the meaning survived. Then the receiver says one word about how it felt. Reshuffle so everyone receives one. Debrief on what makes a compliment specific enough to survive, how receiving felt, and what the group does with compliments outside the room.', '[{"id": "f0", "type": "textarea", "label": "The compliment I received, and the original version:"}, {"id": "f1", "type": "textarea", "label": "The one word I said about how it felt:"}, {"id": "f2", "type": "textarea", "label": "The compliment I gave, and whether it survived the line:"}, {"id": "f3", "type": "textarea", "label": "What the surviving compliments had in common:"}, {"id": "f4", "type": "textarea", "label": "What I usually do with compliments outside this room, and what I might do instead:"}]'::jsonb, array['self-esteem', 'game', 'group', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('blushing-visibility-experiment-sheet', 'Blushing Visibility Experiment Sheet', 'cbt'::resource_kind, 'An experiment comparing how red the client feels against what others can see, using a mirror or a photo at the moment of blushing.', 'Use it to close the gap between a client''s felt blush and the one others actually see.', array['Adults', 'Teens']::text[], '20 minutes, in session then at home', 'Bring on a mild blush in session with a slightly embarrassing question the client agreed to beforehand. At the peak, the client rates how visible they feel the blush is, zero to one hundred, then looks in a mirror or at a photo you take, and rates what they see. Repeat at home with a trusted person who rates it too. The felt number tends to be far higher than the seen one. Discuss what the client does to hide a blush and what that hiding costs.', '[{"id": "f0", "type": "textarea", "label": "How visible I felt the blush was at its peak, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "What I saw in the mirror or photo, and my rating of that:"}, {"id": "f2", "type": "textarea", "label": "What a trusted person rated it when I tried this at home:"}, {"id": "f3", "type": "textarea", "label": "What I usually do to hide a blush, and what that costs me:"}, {"id": "f4", "type": "textarea", "label": "What the gap between felt and seen tells me:"}]'::jsonb, array['social anxiety', 'core CBT', 'behavioral experiment']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('being-boring-on-purpose-willingness-page', 'Being Boring on Purpose Willingness Page', 'act'::resource_kind, 'A page for deliberately saying something plain in conversation and staying present, to loosen the rule that every line must be interesting.', 'Use it to help a client drop the performance standard that keeps them silent in groups.', array['Adults', 'Teens']::text[], 'One week', 'Many socially anxious clients say nothing because the bar for speaking is brilliance. The practice is to say something ordinary on purpose, such as a plain comment on the weather or the food, and notice what happens. Plan three ordinary lines in session. The client rates willingness before each and records the reaction they got. Most reactions are nothing, which is the finding. Connect it to the value of being in the room rather than being impressive.', '[{"id": "f0", "type": "textarea", "label": "The rule my mind has about what I am allowed to say in a group:"}, {"id": "f1", "type": "textarea", "label": "Three ordinary things I will say on purpose this week:"}, {"id": "f2", "type": "textarea", "label": "My willingness before each, zero to ten, and what I actually said:"}, {"id": "f3", "type": "textarea", "label": "What the other people did in response:"}, {"id": "f4", "type": "textarea", "label": "What being ordinary made possible that silence did not:"}]'::jsonb, array['social anxiety', 'core ACT', 'willingness', 'values']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('dear-man-for-joining-the-lunch-table-card', 'DEAR MAN for Joining the Lunch Table Card', 'dbt'::resource_kind, 'A card scripting the DEAR MAN steps for asking to join a group at lunch, break or after class.', 'Use it to give a client a rehearsed, respectful way to ask into a group instead of hovering or eating alone.', array['Teens', 'Adults']::text[], '15 minutes to script, then practice', 'Walk the letters with a real group the client wants to join. Describe: I see you all eat here most days. Express: I would like to join sometimes. Assert: Can I sit with you? Reinforce: I will bring something to share, or I am good at the quiz. Mindful: stay on the ask if the conversation drifts. Appear confident: shoulders down, voice steady. Negotiate: if not today, another day? Rehearse twice in session. Log the attempt and the actual response, whatever it was.', '[{"id": "f0", "type": "textarea", "label": "The group I want to join, and where and when they gather:"}, {"id": "f1", "type": "textarea", "label": "My Describe, Express and Assert lines, in my own words:"}, {"id": "f2", "type": "textarea", "label": "My Reinforce line: what I bring to the table:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my shoulders, voice and eyes:"}, {"id": "f4", "type": "textarea", "label": "My Negotiate line if the answer is not now:"}, {"id": "f5", "type": "textarea", "label": "What happened when I asked, and what I will do next time:"}]'::jsonb, array['social anxiety', 'core DBT', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('plus-one-event-support-plan-for-partners', 'Plus-One Event Support Plan for Partners', 'couples'::resource_kind, 'A plan for a partner attending a social event with the other, covering check-in signals, how long to stay and when to stop helping.', 'Use it to let a couple attend events together in a way that supports without taking over.', array['Couples']::text[], '30 minutes', 'Before a specific event, the anxious partner names what helps: an introduction, a hand on the back, being left alone for ten minutes to try. The supporting partner names what they are willing to do and what they will not do, such as answering questions for the other. Agree on a check-in signal, an arrival plan, a minimum stay and an exit line. Afterward, each writes what worked. Watch for the supporting partner slipping into rescuing, which keeps the other from finding out they can manage.', '[{"id": "f0", "type": "textarea", "label": "Partner who finds events hard: what helps me and what does not:"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what I will do, and what I will not do, at this event:"}, {"id": "f2", "type": "textarea", "label": "Our check-in signal and our exit line:"}, {"id": "f3", "type": "textarea", "label": "The minimum time we will stay, and the plan for the first ten minutes:"}, {"id": "f4", "type": "textarea", "label": "Afterward, each of us: what worked, and what we would change:"}]'::jsonb, array['social anxiety', 'couples', 'support', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('ask-a-kid-question-treasure-chest-craft', 'Ask-a-Kid Question Treasure Chest Craft', 'kids'::resource_kind, 'A craft where the child decorates a small box and fills it with questions to ask other children, then draws one before a playdate or recess.', 'Use it to give a shy child a ready question in hand so starting a conversation is a draw from the chest, not a blank.', array['Children']::text[], '30 minutes to make, then before social times', 'The child decorates a box as a treasure chest and, with the parent, writes or draws ten questions a kid could ask another kid: what is your favorite game, do you have a pet, what did you have for lunch. The parent practices by playing a new kid while the child draws a card and asks. Before recess or a playdate the child picks one card to carry. The parent asks afterward whether the question got used, not whether it went well. Add a new card for every one that got asked.', '[{"id": "f0", "type": "textarea", "label": "The questions in my treasure chest:"}, {"id": "f1", "type": "textarea", "label": "The card I carried today, and whether I asked it:"}, {"id": "f2", "type": "textarea", "label": "What the other kid said back:"}, {"id": "f3", "type": "textarea", "label": "A question I want to add to the chest:"}, {"id": "f4", "type": "textarea", "label": "Parent note: how the practice went when I played the new kid, and what I asked afterward:"}]'::jsonb, array['social anxiety', 'children', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('grief-support-team-roles-sheet', 'Grief Support Team Roles Sheet', 'worksheet'::resource_kind, 'A sheet for naming who in the client''s life can hold which part of grief: the practical, the listening, the distraction and the remembering.', 'Use it to spread a grieving client''s needs across several people instead of asking one person for everything.', array['Adults', 'Teens']::text[], '25 minutes', 'Grieving clients often lean on one person until that person wears out, or on no one. List four roles: someone for errands and forms, someone who can hear the hard parts, someone for an ordinary evening, and someone who knew the person and will say their name. Match a real person to each, including people the client has not asked yet. Write the ask for one of them. The clinician may be in the listening role for now; name that too.', '[{"id": "f0", "type": "textarea", "label": "Someone who can help with the practical pieces, and what I would ask them to do:"}, {"id": "f1", "type": "textarea", "label": "Someone who can hear the hard parts without fixing, and how often I could call on them:"}, {"id": "f2", "type": "textarea", "label": "Someone for an ordinary evening that is not about the loss:"}, {"id": "f3", "type": "textarea", "label": "Someone who knew them and will say their name with me:"}, {"id": "f4", "type": "textarea", "label": "The person I have been asking for all of this, and what I will tell them:"}, {"id": "f5", "type": "textarea", "label": "The one ask I will make this week, in my words:"}]'::jsonb, array['grief and loss', 'support', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('empty-chair-conversation-pacing-page', 'Empty Chair Conversation Pacing Page', 'act'::resource_kind, 'A page for an in-session empty chair conversation with the person who died, with pacing choices and a values-based closing.', 'Use it to let a client say what went unsaid, at a pace they control, and leave with something to carry.', array['Adults', 'Teens']::text[], 'Full session, in session only', 'Offer the chair and let the client decide how close to sit and how long to talk. Before starting, they choose a stop word and whether they want to speak as themselves only or also reply as the person. Keep the conversation in the room; it is not homework. Pause when breathing changes. Close by asking what the person would want the client''s next week to hold, and write one small action from the answer. Record only the pacing and the closing, not the words spoken.', '[{"id": "f0", "type": "textarea", "label": "How I want to do this today: how long, how close, and whether I will reply as them:"}, {"id": "f1", "type": "textarea", "label": "My stop word, and what I want you to do when I use it:"}, {"id": "f2", "type": "textarea", "label": "After: how the pacing felt, and whether I want more or less next time:"}, {"id": "f3", "type": "textarea", "label": "What they would want my next week to hold, in their words as I imagine them:"}, {"id": "f4", "type": "textarea", "label": "One small action from that for this week:"}]'::jsonb, array['grief and loss', 'core ACT', 'values', 'pacing']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('grieving-at-different-speeds-talk-sheet-for-partners', 'Grieving at Different Speeds Talk Sheet for Partners', 'couples'::resource_kind, 'A sheet for partners mourning the same loss differently, naming each one''s grief shape and what each needs the other to stop assuming.', 'Use it to keep two different griefs from becoming a judgment about who loved more.', array['Couples']::text[], 'Full session', 'One partner cries and talks; the other works and goes quiet. Each reads the other''s style as wrong. Have each describe their own grief in behaviors, when it hits, what they do with it, and what they wish the other understood. Then each names one assumption they have made about the other''s grief and asks whether it is true. Agree on one shared ritual and one separate space. Watch for the quiet partner being pushed to perform grief in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what my grief looks like in behaviors, when it hits and what I do with it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what my grief looks like in behaviors, when it hits and what I do with it:"}, {"id": "f2", "type": "textarea", "label": "An assumption each of us has made about the other''s grief, and whether it is true:"}, {"id": "f3", "type": "textarea", "label": "What each of us needs the other to stop saying or doing:"}, {"id": "f4", "type": "textarea", "label": "One shared ritual for remembering them, and one separate space each of us gets:"}]'::jsonb, array['grief and loss', 'couples', 'communication', 'support']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('story-stones-of-our-times-together-craft', 'Story Stones of Our Times Together Craft', 'kids'::resource_kind, 'A craft where the child paints a stone for each memory of the person or pet they lost and tells the story of each to a parent.', 'Use it to give a child a way to keep memories in their hands and tell them one at a time.', array['Children']::text[], '45 minutes, then as needed', 'Gather smooth stones. The child paints a picture on each for one memory: the park, the pancakes, the song. The parent sits alongside, paints their own stones, and asks to hear each story when the child is ready, without adding corrections. Keep the stones in a bag or bowl where the child can reach them. On hard days the child can pull one and tell it again. The parent''s job is to listen and to share their own stone when asked.', '[{"id": "f0", "type": "textarea", "label": "The stones I painted and the memory on each:"}, {"id": "f1", "type": "textarea", "label": "The story I told my grown-up today:"}, {"id": "f2", "type": "textarea", "label": "A stone my grown-up painted and the story they told me:"}, {"id": "f3", "type": "textarea", "label": "Where we keep the stones:"}, {"id": "f4", "type": "textarea", "label": "Parent note: a memory my child holds that I did not know mattered to them:"}]'::jsonb, array['grief and loss', 'children', 'memory', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('their-favorite-things-guessing-game', 'Their Favorite Things Guessing Game', 'game'::resource_kind, 'A gentle group or family game where players guess the lost person''s favorites and the one who knew them best confirms, then shares a story.', 'Use it to let a family or group speak the person''s name and small details with warmth and some laughter.', array['Groups', 'Children', 'Teens', 'Adults']::text[], '25 minutes', 'One player who knew the person well is the judge for a round. The others guess the person''s favorite food, song, saying, place, way to annoy everyone. The judge confirms or corrects and tells a short story about it. Rotate the judge so different people''s knowledge comes out. No points needed, but a tally of correct guesses can keep children engaged. Debrief: what someone learned they did not know, and which detail everyone wants to keep alive.', '[{"id": "f0", "type": "textarea", "label": "The favorites I guessed, and which ones I got right:"}, {"id": "f1", "type": "textarea", "label": "A story someone told about them that I had not heard:"}, {"id": "f2", "type": "textarea", "label": "A detail I knew that nobody else did:"}, {"id": "f3", "type": "textarea", "label": "The thing about them everyone wants to keep alive:"}, {"id": "f4", "type": "textarea", "label": "How it felt to say their name and laugh in the same minute:"}]'::jsonb, array['grief and loss', 'game', 'family', 'memory']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('repair-attempts-i-missed-replay-log', 'Repair Attempts I Missed Replay Log', 'worksheet'::resource_kind, 'A log for replaying a recent argument and finding the moments the other person reached out that the client did not take.', 'Use it to help a client see the exits from an argument that were offered and missed.', array['Adults', 'Teens']::text[], '25 minutes, after an argument', 'Within a day of an argument, the client walks through it like a film and pauses at every moment the other person softened, joked, apologized partway, or changed the subject. Those are repair attempts. Note each, what the client did with it, and what was happening inside them at that second. Most clients find two or three they rode past. Then plan what taking the next one would look like. This is about the client''s side only; the other person''s misses are theirs.', '[{"id": "f0", "type": "textarea", "label": "The argument, in two neutral sentences:"}, {"id": "f1", "type": "textarea", "label": "Moments the other person softened, joked, half-apologized or changed subject:"}, {"id": "f2", "type": "textarea", "label": "What I did at each of those moments:"}, {"id": "f3", "type": "textarea", "label": "What was going on inside me at each one that made it hard to take:"}, {"id": "f4", "type": "textarea", "label": "What taking the next repair attempt would look like, in words I could actually say:"}]'::jsonb, array['relationship issues', 'repair', 'self-monitoring', 'Gottman']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('going-quiet-to-punish-thought-record', 'Going Quiet to Punish Thought Record', 'cbt'::resource_kind, 'A thought record for the moments a client goes quiet to punish or protect, catching the thought, the feeling and the quiet''s purpose.', 'Use it to help a client see what their silence is saying and whether it gets what they want.', array['Adults', 'Teens']::text[], '20 minutes per episode', 'Going quiet at someone is a behavior with a thought under it: they should know what they did, or if I speak I will say something unforgivable. Record the trigger, the thought, the feeling, and what the silence was meant to achieve. Then ask what it actually achieved and what the other person likely concluded. Draft one sentence the client could have said instead that keeps the protection without the punishment. Watch for shame about the pattern; it is common and workable.', '[{"id": "f0", "type": "textarea", "label": "What happened right before I went quiet:"}, {"id": "f1", "type": "textarea", "label": "The thought I had, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What I was feeling, and how strong, zero to ten:"}, {"id": "f3", "type": "textarea", "label": "What the silence was meant to achieve, and what it actually achieved:"}, {"id": "f4", "type": "textarea", "label": "What the other person probably concluded from my silence:"}, {"id": "f5", "type": "textarea", "label": "One sentence I could have said instead:"}]'::jsonb, array['relationship issues', 'core CBT', 'communication', 'conflict']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('fast-skill-for-saying-no-to-a-partner-card', 'FAST Skill for Saying No to a Partner Card', 'dbt'::resource_kind, 'A card for keeping self-respect when declining a partner''s request: Fair, no Apologies, Stick to values, Truthful.', 'Use it to help a client refuse a partner without over-apologizing, lying or caving.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'Clients who cannot say no to a partner usually either cave and resent, or say yes and then do not do it. Walk through FAST with a real request: be fair to both, skip the long apology, name the value you are keeping, tell the truth about why. Script the no in two sentences and rehearse it until it sounds calm rather than defensive. Log each real use and what happened to the relationship afterward, which is usually less than the client feared.', '[{"id": "f0", "type": "textarea", "label": "The request I want to decline, and what usually happens when I try:"}, {"id": "f1", "type": "textarea", "label": "Fair: how I will be fair to both of us in the no:"}, {"id": "f2", "type": "textarea", "label": "No apologies: the sorry I will leave out:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: the value I am keeping by saying no:"}, {"id": "f4", "type": "textarea", "label": "Truthful: the real reason, in one sentence:"}, {"id": "f5", "type": "textarea", "label": "My two-sentence no, and what happened when I used it:"}]'::jsonb, array['relationship issues', 'core DBT', 'FAST', 'boundaries']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('phones-at-the-table-agreement-for-partners', 'Phones at the Table Agreement for Partners', 'couples'::resource_kind, 'An agreement about phones during meals and the first twenty minutes home, with each partner''s exceptions and a reset for slips.', 'Use it to protect a couple''s daily face time from the screens that quietly took it.', array['Couples']::text[], '20 minutes', 'Ask each partner how often they feel they are talking to the top of the other''s head. Agree on two phone-free windows: meals together and the first stretch after both are home. Each partner lists exceptions they truly need, such as an on-call shift, and the other accepts them. Decide where the phones go and what either partner says when the other slips, in a tone they both agree to. Review after two weeks and keep the windows that worked.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when I feel I am talking to the top of your head:"}, {"id": "f1", "type": "textarea", "label": "Partner B: when I feel I am talking to the top of your head:"}, {"id": "f2", "type": "textarea", "label": "Our two phone-free windows, and where the phones will be:"}, {"id": "f3", "type": "textarea", "label": "Each partner''s exceptions, and whether the other accepts them:"}, {"id": "f4", "type": "textarea", "label": "What we say when one of us slips, in a tone we both agreed to:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what the windows gave us, and what we will keep:"}]'::jsonb, array['relationship issues', 'couples', 'connection', 'boundaries']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('two-sides-narrator-swap-game', 'Two Sides Narrator Swap Game', 'game'::resource_kind, 'A pairs game where each person narrates a shared disagreement from the other''s point of view, and the other grades the accuracy.', 'Use it to let two people hear their own position told back to them, and find what the other missed.', array['Couples', 'Groups', 'Teens']::text[], '30 minutes', 'Pick a mild, finished disagreement. Player A tells the story as player B, in the first person, including what B felt and wanted. B grades the accuracy one to ten and adds the piece that was missing. Then swap. Rules: no sarcasm in the other''s voice, and the grader must name one thing the narrator got right before any correction. Debrief on what it was like to hear yourself played, and what each learned the other did not understand.', '[{"id": "f0", "type": "textarea", "label": "The disagreement we chose:"}, {"id": "f1", "type": "textarea", "label": "How it felt to tell the story as the other person:"}, {"id": "f2", "type": "textarea", "label": "The grade I got, and the piece I had missed:"}, {"id": "f3", "type": "textarea", "label": "The grade I gave, and the thing the other person got right about me:"}, {"id": "f4", "type": "textarea", "label": "What I understand about the other person''s side now that I did not before:"}]'::jsonb, array['relationship issues', 'game', 'perspective taking', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('body-signals-that-mean-pause-sheet', 'Body Signals That Mean Pause Sheet', 'worksheet'::resource_kind, 'A sheet for noticing the client''s own early signs of getting overwhelmed in session, and the pause plan each one triggers.', 'Use it to give a client and clinician a shared early-warning system for pacing difficult work.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Before any work near the hard material, map the client''s own signals: a change in breathing, looking at the floor, going quiet, a hand on the neck. Agree on what each one means, from slow down to stop for today, and what the clinician will do. The client does not have to say the words when the signal appears; the sheet has already said them. Revisit the sheet as the work goes on, since signals change. This sheet never asks about the events themselves.', '[{"id": "f0", "type": "textarea", "label": "The first things that happen in my body when something gets to be too much:"}, {"id": "f1", "type": "textarea", "label": "What I tend to do (go quiet, look away, laugh, change the subject):"}, {"id": "f2", "type": "textarea", "label": "What each signal means: slow down, change direction, or stop for today:"}, {"id": "f3", "type": "textarea", "label": "What I want you to do when you see each signal:"}, {"id": "f4", "type": "textarea", "label": "What helps me come back after a pause:"}]'::jsonb, array['sexual abuse', 'pacing', 'safety', 'grounding']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('damaged-goods-belief-gentle-check-sheet', 'Damaged Goods Belief Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle sheet for the belief that the client is permanently damaged, looking at where it came from and at the evidence in the present.', 'Use it to begin loosening a belief about being damaged without reopening what caused it.', array['Adults', 'Teens']::text[], '30 minutes, in session', 'Use in session, and only when the client has named this belief themselves. Write the belief and rate it. Ask where the words came from; they are often someone else''s. Then look at the present only: what the client does, who trusts them, what they care for. Do not list the evidence for the belief and do not go into what happened. Close by writing one sentence the client finds even slightly more true than the belief, and leave the belief itself on the page unresolved if that is where it is.', '[{"id": "f0", "type": "textarea", "label": "The belief, in the words I use, and how much I believe it, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "Whose words these were first, if I know:"}, {"id": "f2", "type": "textarea", "label": "Things I do in my present life that a damaged person supposedly could not:"}, {"id": "f3", "type": "textarea", "label": "People and creatures who trust me, and what they trust me with:"}, {"id": "f4", "type": "textarea", "label": "One sentence that feels even slightly more true than the belief:"}]'::jsonb, array['sexual abuse', 'core CBT', 'core beliefs', 'self-blame']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('choosing-who-knows-values-page', 'Choosing Who Knows Values Page', 'act'::resource_kind, 'A page for deciding, by the client''s own values, who in their life learns about their history and how much, with no pressure to tell anyone.', 'Use it to make disclosure a chosen act in service of something the client cares about, rather than an obligation or an accident.', array['Adults', 'Teens']::text[], '30 minutes', 'Clients sometimes feel they owe the truth to everyone, or fear it will come out on its own. Separate the two. For each person under consideration, the client names the value that telling would serve, such as closeness or honesty, and the value that not telling would serve, such as privacy or safety. Both are legitimate. Decide on a headline only version for anyone they do choose. Nothing on this page asks for the details, and no choice here is permanent.', '[{"id": "f0", "type": "textarea", "label": "People I am thinking about telling, and the value telling each one would serve:"}, {"id": "f1", "type": "textarea", "label": "The value that not telling each of them would serve:"}, {"id": "f2", "type": "textarea", "label": "The headline-only version I would use if I chose to tell someone:"}, {"id": "f3", "type": "textarea", "label": "What I want from a person after they know:"}, {"id": "f4", "type": "textarea", "label": "My choice for now for each person, knowing I can change it:"}]'::jsonb, array['sexual abuse', 'core ACT', 'values', 'support']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('counting-colors-grounding-card', 'Counting Colors Grounding Card', 'dbt'::resource_kind, 'A card for grounding by finding and counting every object of one color in the room, then switching to a second color.', 'Use it to give a client a quick outward-facing anchor that works in any room without moving.', array['Adults', 'Teens', 'Children']::text[], 'Two minutes, as needed', 'Pick a color and count every object that has it, silently or aloud, then pick a second color and do it again. The card lists the steps and leaves space for the usual rooms the client needs it in. Practice in session until the client can do it in under a minute. It works because it needs eyes and attention, both of which the pull of a memory tends to take. For a child, the parent calls the color and counts alongside. Log where it was used and what came back first.', '[{"id": "f0", "type": "textarea", "label": "The rooms or places I most need this in:"}, {"id": "f1", "type": "textarea", "label": "The two colors I used today, and how many of each I found:"}, {"id": "f2", "type": "textarea", "label": "What came back first: the room, my body, or the sounds?"}, {"id": "f3", "type": "textarea", "label": "How long it took, roughly:"}, {"id": "f4", "type": "textarea", "label": "A place I want to practice it before I need it there:"}]'::jsonb, array['sexual abuse', 'core DBT', 'grounding', 'distress tolerance']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('uh-oh-feeling-body-signals-drawing-activity', 'Uh-Oh Feeling Body Signals Drawing Activity', 'kids'::resource_kind, 'A drawing activity where the child colors where the uh-oh feeling shows up in their body and names the grown-ups they can tell.', 'Use it to teach a child to trust the uh-oh feeling and to connect it to telling, in a session led by a parent and clinician together.', array['Children']::text[], '25 minutes', 'On a body outline, the child colors where the uh-oh feeling lives: a tummy flip, a tight throat, hot cheeks. Then the parent and child list the grown-ups the child can tell when the feeling comes, and practice the sentence I have an uh-oh feeling. Keep it general and matter-of-fact; the activity is about the signal and the telling, not about any event. If a child discloses during the activity, stay calm, believe them, do not ask leading questions, and follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Where the uh-oh feeling shows up in my body, colored on my outline:"}, {"id": "f1", "type": "textarea", "label": "What the uh-oh feeling feels like, in my words:"}, {"id": "f2", "type": "textarea", "label": "The grown-ups I can tell when I get it:"}, {"id": "f3", "type": "textarea", "label": "My sentence: I have an uh-oh feeling, and what happens after I say it:"}, {"id": "f4", "type": "textarea", "label": "Parent note: how I will respond when my child tells me they have the feeling:"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('discomfort-budget-for-a-valued-day-page', 'Discomfort Budget for a Valued Day Page', 'act'::resource_kind, 'A page where the client sets how much discomfort they are willing to spend on one valued day and plans where it goes.', 'Use it to reframe a hard day as discomfort spent on purpose, with coping skills placed where the spending peaks.', array['Adults', 'Teens']::text[], '20 minutes the night before', 'Pick a day with something valued and hard in it. The client sets a discomfort budget, zero to one hundred, and allocates it across the day''s moments: twenty for the commute, forty for the meeting. Then they place one coping skill at each spending point. The budget is not a cap on feelings; it is a decision to spend. Afterward they record where the real cost landed. Over time this shows which moments cost more than expected and which skills earned their place.', '[{"id": "f0", "type": "textarea", "label": "The day and the valued thing in it:"}, {"id": "f1", "type": "textarea", "label": "My discomfort budget for the day, zero to one hundred, and why I am willing to spend it:"}, {"id": "f2", "type": "textarea", "label": "Where I expect to spend it, moment by moment:"}, {"id": "f3", "type": "textarea", "label": "The coping skill placed at each spending point:"}, {"id": "f4", "type": "textarea", "label": "Afterward: where the real cost landed, and which skill earned its place:"}]'::jsonb, array['coping skills', 'core ACT', 'willingness', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-movement-menu-card', 'Self-Soothe With Movement Menu Card', 'dbt'::resource_kind, 'A card of movements that soothe rather than burn off: slow stretches, rocking, swaying, a slow loop walked, with the client''s own picks.', 'Use it to give a client who cannot sit still a self-soothe menu built on gentle movement.', array['Adults', 'Teens']::text[], '15 minutes to build, then as needed', 'Some clients cannot use a sensory kit because stillness makes it worse. Build a menu of slow movements: neck rolls, swaying with feet planted, a slow walk around the block, rocking in a chair, stretching against a wall. Try three in session and rate how settled the client feels after each. Keep the pace slow; fast movement is a different skill. The card lists the client''s top four with where each can be done without drawing attention.', '[{"id": "f0", "type": "textarea", "label": "The slow movements I tried, and how settled I felt after each, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "My top four, and where I can do each one without anyone noticing:"}, {"id": "f2", "type": "textarea", "label": "A time this week I used one, and how long until I felt settled:"}, {"id": "f3", "type": "textarea", "label": "A movement that made things worse, and what that tells me:"}, {"id": "f4", "type": "textarea", "label": "A place I need a movement I do not have yet:"}]'::jsonb, array['coping skills', 'core DBT', 'self-soothing', 'distress tolerance']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('coping-kit-swap-for-partners', 'Coping Kit Swap for Partners', 'couples'::resource_kind, 'An activity where each partner builds a small coping kit for the other, based on what they have noticed helps, and explains each item.', 'Use it to show a couple how well they already know each other''s coping, and where they have guessed wrong.', array['Couples']::text[], 'Full session plus one week', 'Between sessions, each partner assembles a small kit for the other: a playlist, a tea, a note, a photo, a fidget, a list of three things to say. In session they hand them over and explain each item. The receiver says what landed, what missed, and what is missing. Partners are often moved by being studied this closely, and corrected items teach as much as the right ones. Agree where each kit lives and when either partner may hand the other theirs.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I put in your kit, and why each item:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I put in your kit, and why each item:"}, {"id": "f2", "type": "textarea", "label": "Receiving my kit: what landed, what missed, and what is missing:"}, {"id": "f3", "type": "textarea", "label": "Something my partner noticed about my coping that I had not said out loud:"}, {"id": "f4", "type": "textarea", "label": "Where each kit lives, and when either of us may hand the other theirs:"}]'::jsonb, array['coping skills', 'couples', 'support', 'self-soothing']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('coping-skill-keychain-craft', 'Coping Skill Keychain Craft', 'kids'::resource_kind, 'A craft where the child makes a keychain of small cards, one coping skill per card, to clip to a backpack and flip through when upset.', 'Use it to put a child''s coping skills in their pocket where they will be at school and in the car.', array['Children']::text[], '30 minutes to make, then as needed', 'The child cuts five small cards and draws one skill on each: belly breath, squeeze and release, count five things, ask for a hug, get a drink of water. The parent laminates or tapes them, punches a corner and clips them on a ring. The child picks where it lives: backpack zipper, belt loop, bedside. Practice flipping through and picking one when calm. The parent reminds with one line, check your keychain, instead of naming a skill for the child.', '[{"id": "f0", "type": "textarea", "label": "The five skills on my cards, and the picture for each:"}, {"id": "f1", "type": "textarea", "label": "Where my keychain lives:"}, {"id": "f2", "type": "textarea", "label": "A time I flipped through it this week, and the card I picked:"}, {"id": "f3", "type": "textarea", "label": "A card I want to swap out, and what I would put instead:"}, {"id": "f4", "type": "textarea", "label": "Parent note: what happened when I said check your keychain instead of telling my child what to do:"}]'::jsonb, array['coping skills', 'children', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('skill-or-no-skill-buzzer-game', 'Skill or No Skill Buzzer Game', 'game'::resource_kind, 'A fast group game where the leader reads a reaction to a hard moment and players buzz in to call it a coping skill or not, and say why.', 'Use it to sharpen a group''s sense of what counts as coping and what only feels like it in the moment.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Prepare cards describing reactions: took a walk, scrolled for two hours, called a friend, picked a fight, cleaned the kitchen, ate until sick, wrote the thought down. The leader reads one; the first to buzz calls skill or no skill and defends it in one sentence. The group may overturn with a majority. Some cards are genuinely both, which makes the best discussion. Debrief: what made the group call something a skill, and which of the no-skill cards each player uses most.', '[{"id": "f0", "type": "textarea", "label": "The card I buzzed on, my call, and my one-sentence reason:"}, {"id": "f1", "type": "textarea", "label": "A card the group overturned, and why:"}, {"id": "f2", "type": "textarea", "label": "A card that was genuinely both, and what made the difference:"}, {"id": "f3", "type": "textarea", "label": "The no-skill card I use most in real life:"}, {"id": "f4", "type": "textarea", "label": "A skill card I want to use more, and when:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('avoidance-detours-mileage-log', 'Avoidance Detours Mileage Log', 'worksheet'::resource_kind, 'A log of the extra miles, minutes and money a client spends each week routing around the thing they fear.', 'Use it to make the hidden cost of avoidance concrete before asking a client to approach anything.', array['Adults', 'Teens']::text[], 'One week', 'Fear of bridges, elevators, dogs, highways or dentists all leave a trail of detours. For one week the client logs each: the thing avoided, the route taken instead, and the extra time, distance or money. Include the trips not taken at all. Add it up together at the week''s end. Clients tend to underestimate until the total is on paper. The log is not an argument; it is a receipt, and the client decides what they want to do about the bill.', '[{"id": "f0", "type": "textarea", "label": "Each detour this week: what I avoided, what I did instead, and the extra time, distance or money:"}, {"id": "f1", "type": "textarea", "label": "Trips or plans I dropped entirely because of the fear:"}, {"id": "f2", "type": "textarea", "label": "The week''s total in minutes, miles and dollars:"}, {"id": "f3", "type": "textarea", "label": "What I could have done with that total:"}, {"id": "f4", "type": "textarea", "label": "What I want to do about the bill, if anything, and why:"}]'::jsonb, array['phobias', 'avoidance', 'self-monitoring']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('feared-image-versus-photograph-comparison-sheet', 'Feared Image Versus Photograph Comparison Sheet', 'cbt'::resource_kind, 'A sheet for drawing the feared thing as the mind pictures it, then comparing it with a real photograph, feature by feature.', 'Use it to show a client how the mind''s picture of the feared thing differs from the actual thing.', array['Adults', 'Teens', 'Children']::text[], '25 minutes', 'Ask the client to draw or describe the feared thing as it appears in their mind: size, speed, teeth, closeness. Then look at a real photograph together, chosen at a distance and size the client agrees to. Compare feature by feature. The mind''s version is usually larger, faster and closer. Ask what the mind added and why it might do that. For children, the parent draws too. This sheet is about the image, not about approaching the thing yet.', '[{"id": "f0", "type": "textarea", "label": "The feared thing as I picture it: size, speed, distance, details:"}, {"id": "f1", "type": "textarea", "label": "The real photograph, feature by feature:"}, {"id": "f2", "type": "textarea", "label": "What my mind added or exaggerated:"}, {"id": "f3", "type": "textarea", "label": "Why my mind might do that:"}, {"id": "f4", "type": "textarea", "label": "How my fear rating changed, if at all, from before the comparison to after:"}]'::jsonb, array['phobias', 'core CBT', 'exposure', 'thinking traps']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('approach-posture-opposite-action-card-for-fear', 'Approach Posture Opposite Action Card for Fear', 'dbt'::resource_kind, 'A card for the body half of opposite action to fear: feet toward the thing, shoulders down, chin level, hands open, at every step.', 'Use it to give a client a physical stance to take at each rung of a fear ladder.', array['Adults', 'Teens']::text[], 'Ten minutes to learn, then at each step', 'Fear bends the body away: leaning back, shoulders up, hands clenched. Opposite action starts with the posture. Teach it standing: toes pointed at the feared thing, weight slightly forward, shoulders down, chin level, palms open. Hold it for a slow breath before each step on a ladder and during the step itself. Practice in session facing a picture or the door. Log each use, the posture the client noticed themselves in before correcting, and what the step was like with the stance.', '[{"id": "f0", "type": "textarea", "label": "The step I was taking, and the posture I caught myself in before correcting:"}, {"id": "f1", "type": "textarea", "label": "The approach posture, piece by piece, as I set it:"}, {"id": "f2", "type": "textarea", "label": "What the step felt like with my body pointed at it:"}, {"id": "f3", "type": "textarea", "label": "The piece of the posture that is hardest to hold:"}, {"id": "f4", "type": "textarea", "label": "My next step, and when I will take the stance for it:"}]'::jsonb, array['phobias', 'core DBT', 'opposite action', 'exposure']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('friendly-spider-puppet-making-craft', 'Friendly Spider Puppet Making Craft', 'kids'::resource_kind, 'A craft where the child makes a soft spider puppet, gives it a name and a voice, and lets it visit their hand while a parent plays along.', 'Use it to let a child get used to the shape and movement of a feared creature through something they made and control.', array['Children']::text[], '40 minutes to make, then play', 'Use a pom-pom or sock and pipe cleaner legs. The child decides the colors and the name and makes it as silly as they like. The parent voices the spider as nervous and polite, asking permission before it walks onto the child''s hand. The child is always in charge of how close it comes and can say stop. Over days, the puppet visits the shoulder, sits on a book the child is reading, and eventually watches a video of a real spider with them. This is the first rung only; the parent never surprises the child with the puppet.', '[{"id": "f0", "type": "textarea", "label": "My spider''s name, colors and voice:"}, {"id": "f1", "type": "textarea", "label": "How close my spider came today, and who decided:"}, {"id": "f2", "type": "textarea", "label": "Something my spider said that made me laugh:"}, {"id": "f3", "type": "textarea", "label": "What I want my spider to try next:"}, {"id": "f4", "type": "textarea", "label": "Parent note: the rule we keep about asking first, and what I noticed in my child''s body this week:"}]'::jsonb, array['phobias', 'children', 'play', 'parenting']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('brave-bets-prediction-game', 'Brave Bets Prediction Game', 'game'::resource_kind, 'A group game where players bet pretend chips on what will happen when a member takes a small step toward a fear, then watch and settle up.', 'Use it to make predictions public, watch them meet reality, and let the group carry some of the fear for the person stepping.', array['Groups', 'Teens', 'Adults']::text[], '40 minutes', 'Each round, one volunteer names a small step they will take in the room or just outside it: holding a photo, standing on a chair, letting a dog be led past. Everyone, including the volunteer, bets chips on outcomes: nothing happens, I get scared and stay, I get scared and leave. The step is taken; chips are settled. Over several rounds the house pattern becomes obvious. Debrief on how the volunteer''s bets compared with the group''s, and what the chips say about how fear predicts.', '[{"id": "f0", "type": "textarea", "label": "The step I volunteered, and where I put my chips:"}, {"id": "f1", "type": "textarea", "label": "Where the group put theirs:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "How my own bets compared with reality across the rounds:"}, {"id": "f4", "type": "textarea", "label": "What the chips say about how my fear makes predictions:"}]'::jsonb, array['phobias', 'game', 'group', 'exposure']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('senses-not-looks-day-plan-sheet', 'Senses Not Looks Day Plan Sheet', 'worksheet'::resource_kind, 'A plan for one day built around what the body will feel, hear, taste and do, with no appearance check anywhere in it.', 'Use it to give a client a lived day in which the body is an instrument of experience rather than an object to inspect.', array['Adults', 'Teens']::text[], 'One day', 'Plan the day hour by hour around sensory experiences: warm shower, music on a walk, a favorite texture of clothing, sunlight on skin, a good meal eaten slowly. Mirrors are covered or passed without stopping. At the end of the day the client records which hours they stayed in the senses and when the inspecting mind came back. Expect it to come back often; the point is the contrast. Repeat on a weekend and compare the two days.', '[{"id": "f0", "type": "textarea", "label": "My day, hour by hour, in what my body will feel, hear, taste and do:"}, {"id": "f1", "type": "textarea", "label": "What I will do about mirrors and photos today:"}, {"id": "f2", "type": "textarea", "label": "The hours I stayed in my senses:"}, {"id": "f3", "type": "textarea", "label": "When the inspecting mind came back, and what brought it:"}, {"id": "f4", "type": "textarea", "label": "What my body was for today, in one sentence:"}]'::jsonb, array['body image', 'mindfulness', 'planning']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('looks-fix-everything-belief-test-sheet', 'Looks Fix Everything Belief Test Sheet', 'cbt'::resource_kind, 'A sheet testing the belief that a changed appearance would fix the client''s life, by checking which problems looks actually touch.', 'Use it to separate the problems a client has from the appearance they blame for all of them.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the belief as the client holds it: if I looked different, everything would be better. List everything they want to be better: friendships, work, a relationship, confidence, energy. For each, ask how appearance would change it, specifically, and whether they know anyone who looks the way they wish to and still has that problem. Most problems turn out to have other handles. Pick one problem and one handle that has nothing to do with looks to work on first.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it, zero to one hundred:"}, {"id": "f1", "type": "textarea", "label": "Everything I want to be better in my life:"}, {"id": "f2", "type": "textarea", "label": "For each, exactly how looking different would change it:"}, {"id": "f3", "type": "textarea", "label": "People who look the way I wish to and still have that problem:"}, {"id": "f4", "type": "textarea", "label": "One problem on the list, and one handle for it that has nothing to do with looks:"}]'::jsonb, array['body image', 'core CBT', 'thinking traps', 'behavioral experiment']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('body-thoughts-on-a-billboard-defusion-page', 'Body Thoughts on a Billboard Defusion Page', 'act'::resource_kind, 'A defusion page where the client imagines each appearance thought as a billboard on a highway, notices it, and keeps driving.', 'Use it to help a client let appearance thoughts pass by instead of pulling over to argue with each one.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'Describe the highway: billboards on both sides, each with an appearance thought in huge letters. The client can read them, notice who paid for them, and keep driving toward where they are going. Pulling over is checking, comparing or changing clothes. Practice with three live thoughts in session. The page asks who paid for each billboard, which is often a specific person or an industry, and where the client is driving, which is the value. Log billboards seen and times pulled over.', '[{"id": "f0", "type": "textarea", "label": "The billboards I passed today, in their own words:"}, {"id": "f1", "type": "textarea", "label": "Who paid for each one, as best I can tell:"}, {"id": "f2", "type": "textarea", "label": "Where I was driving when I passed them (the value or the plan):"}, {"id": "f3", "type": "textarea", "label": "Times I pulled over, and what pulling over looked like:"}, {"id": "f4", "type": "textarea", "label": "What it was like to keep driving past the loudest one:"}]'::jsonb, array['body image', 'core ACT', 'defusion', 'values']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('photo-taking-and-posting-agreement-for-partners', 'Photo Taking and Posting Agreement for Partners', 'couples'::resource_kind, 'An agreement about photos: asking before taking, before posting, and what each partner wants said when they dislike a picture.', 'Use it to take the appearance pressure out of a couple''s photos and the posting that follows.', array['Couples']::text[], '20 minutes', 'Photos are a common flashpoint when one partner struggles with their appearance. Each partner names what they want: ask before you take, show me before you post, delete without a debate, or no comments on how I look in it. The other partner says what they can agree to. Add what each wants said when they see a photo and hate it; usually not reassurance about looks but a word about the moment. Review after one event with photos.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I want around taking, showing and posting photos of me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I want around taking, showing and posting photos of me:"}, {"id": "f2", "type": "textarea", "label": "What each of us can agree to from the other''s list:"}, {"id": "f3", "type": "textarea", "label": "What I want you to say when I see a photo and hate how I look:"}, {"id": "f4", "type": "textarea", "label": "After the next event with photos: how the agreement held, and one edit:"}]'::jsonb, array['body image', 'couples', 'boundaries', 'communication']::text[], '2026-11-13T15:00:00+00:00'::timestamptz),
  ('inside-qualities-guess-who-game', 'Inside Qualities Guess Who Game', 'game'::resource_kind, 'A group game where the clues to a member''s identity may describe anything about them except how they look.', 'Use it to practice describing and recognizing people by who they are rather than by their appearance.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Each player writes four clues about themselves: a habit, a kindness, a skill, a quirk, nothing about appearance. Clues go in a hat. The leader reads one set at a time and the group guesses who it is; appearance guesses are disallowed and lose a point. After the guess, the person says which clue they liked being known by. Debrief on how easy or hard it was to write four non-appearance clues, and what the group noticed about how it usually identifies people.', '[{"id": "f0", "type": "textarea", "label": "My four clues, none about how I look:"}, {"id": "f1", "type": "textarea", "label": "How hard it was to write them, and what my mind kept offering instead:"}, {"id": "f2", "type": "textarea", "label": "Whether the group guessed me, and which clue did it:"}, {"id": "f3", "type": "textarea", "label": "The clue I liked being known by:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about how I describe myself and others:"}]'::jsonb, array['body image', 'game', 'group', 'strengths']::text[], '2026-11-13T15:00:00+00:00'::timestamptz)
