-- Clinician library: the 125 therapist_resources rows added on 2026-11-13 (five of every kind
-- and five on each of the eighteen daily topics). Generated from data/therapist-resources.json with
--   python3 tools/therapist_resources_sql.py --since 2026-11-13
-- An upsert on slug, so applying it twice is harmless.
on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  summary    = excluded.summary,
  goal       = excluded.goal,
  audience   = excluded.audience,
  duration   = excluded.duration,
  body_md    = excluded.body_md,
  fields     = excluded.fields,
  tags       = excluded.tags,
  created_at = excluded.created_at;
